insert into public.quiz_tests (service_id, label, draw, pass, minutes) values ('ar-condicionado', 'Ar-condicionado', 20, 14, 20)
insert into private.quiz_questions (id, service_id, topic, question, options, why, source, active, updated_at) values
  ('ar-01', 'ar-condicionado', 'seguranca', 'Antes de abrir a evaporadora para uma manutenção, o que fazer primeiro?', array['Desligar o disjuntor do aparelho', 'Desligar pelo controle remoto e esperar a turbina parar', 'Colocar no modo ventilar para a placa não esquentar', 'Tirar o filtro com o aparelho funcionando para ver o fluxo']::text[], 'O controle remoto só desliga a operação, e a placa continua energizada. O manual pede energia DESLIGADA em qualquer manutenção.', 'Manual Midea Springer', true, now()),
  ('ar-02', 'ar-condicionado', 'seguranca', 'Como procurar um vazamento de fluido refrigerante?', array['Com espuma ou detector, nunca com chama', 'Com um isqueiro perto das conexões', 'Cheirando as conexões, que o fluido tem cheiro forte', 'Ligando o aparelho no máximo e ouvindo o chiado']::text[], 'O manual alerta para risco de explosão: jamais usar chama viva para detectar vazamento.', 'Manual Midea Springer', true, now()),
  ('ar-03', 'ar-condicionado', 'instalacao', 'Para pressurizar a tubulação e testar vazamento, o que usar?', array['Nitrogênio seco, com regulador', 'Oxigênio', 'Ar comprimido do compressor de pintura, com filtro', 'O próprio compressor do aparelho, puxando ar da linha']::text[], 'Oxigênio com óleo pode explodir, e ar comprimido coloca umidade no sistema. O fabricante pede nitrogênio seco com regulador e proíbe comprimir ar com o compressor da unidade.', 'Manual Midea Springer', true, now()),
  ('ar-04', 'ar-condicionado', 'instalacao', 'Na hora de soldar a tubulação de cobre, o que fazer por dentro do tubo?', array['Passar nitrogênio durante a solda', 'Nada, só soldar por fora com bastante fluxo', 'Passar óleo por dentro para o cobre não queimar', 'Deixar o tubo aberto nas pontas para sair a fumaça']::text[], 'Sem nitrogênio, forma óxido de cobre por dentro, e ele depois entope filtro e capilar.', 'Manual Midea Springer', true, now()),
  ('ar-05', 'ar-condicionado', 'instalacao', 'Antes de encaixar a porca no tubo, o que não pode esquecer?', array['Pôr a porca antes de flangear', 'Fazer o flange e depois passar a porca pela outra ponta', 'Passar fita veda rosca na rosca da porca', 'Passar cola na ponta do flange para vedar melhor']::text[], 'Depois de flangeado, a porca não passa mais pela ponta, e é preciso cortar e refazer o flange.', 'Manual Midea Springer', true, now()),
  ('ar-06', 'ar-condicionado', 'instalacao', 'Como fazer o aperto final da porca flange na válvula da condensadora?', array['Com duas chaves, no torque da tabela', 'Com uma chave só', 'Na mão, bem firme, para não estragar o flange', 'Com chave de cano, que segura melhor sem escapar']::text[], 'Duas chaves evitam torcer a válvula. Aperto demais racha o flange, e de menos vaza.', 'Manual Midea Springer', true, now()),
  ('ar-07', 'ar-condicionado', 'instalacao', 'Como isolar as linhas de sucção e de expansão?', array['Cada linha com o seu isolamento, separadas', 'As duas juntas num isolamento só', 'Só a linha fina', 'Não precisa isolar se ficar dentro da parede']::text[], 'O manual pede isolar as linhas separadamente. Juntas, uma troca calor com a outra e o aparelho rende menos.', 'Manual Midea Springer', true, now()),
  ('ar-08', 'ar-condicionado', 'instalacao', 'Ao dobrar o tubo de cobre, qual é o cuidado?', array['Com curvador, sem amassar', 'Na mão, bem fechado, para ocupar menos espaço na parede', 'Esquentando com maçarico e dobrando em ângulo reto', 'Pode amassar um pouco na curva, que não muda nada']::text[], 'Dobra amassada estrangula o fluxo. O manual pede raio de dobra não inferior a 100 mm.', 'Manual Midea Springer', true, now()),
  ('ar-09', 'ar-condicionado', 'vacuo', 'Como deve ser feito o vácuo da tubulação e da evaporadora?', array['Com bomba de vácuo e vacuômetro', 'Usando o próprio compressor do aparelho', 'Soltando um pouco do gás da condensadora para empurrar o ar', 'Não precisa: a evaporadora vem selada']::text[], 'O manual proíbe usar o compressor para fazer vácuo. O vácuo com bomba tira o ar e a umidade, e o vacuômetro confirma o resultado.', 'Manual Midea Springer', true, now()),
  ('ar-10', 'ar-condicionado', 'vacuo', 'Durante o vácuo, como ficam as válvulas de serviço da condensadora?', array['Fechadas', 'Abertas, para fazer vácuo no aparelho todo de uma vez', 'Só a de sucção aberta, para a bomba puxar o ar', 'Tanto faz, desde que o vacuômetro esteja ligado']::text[], 'O fluido vem guardado na condensadora. Abrir as válvulas no vácuo joga essa carga na bomba.', 'Manual Midea Springer', true, now()),
  ('ar-11', 'ar-condicionado', 'vacuo', 'Qual é a faixa de vácuo recomendada pelo fabricante?', array['Entre 250 e 500 mícrons (μmHg)', 'Até o manômetro marcar zero', 'Cerca de 5.000 mícrons', 'Basta ligar a bomba por 2 minutos']::text[], 'O manual indica 250 a 500 μmHg, medido com vacuômetro. O manômetro do manifold não tem precisão para isso.', 'Manual Midea Springer', true, now()),
  ('ar-12', 'ar-condicionado', 'vacuo', 'Você desliga a bomba e a leitura do vacuômetro continua subindo sem parar. O que isso indica?', array['Vazamento no sistema', 'Vácuo perfeito', 'Bomba com óleo novo', 'Excesso de nitrogênio']::text[], 'Se a pressão não estabiliza e continua subindo, há fuga. É preciso achar e corrigir antes de seguir.', 'Manual Midea Springer', true, now()),
  ('ar-13', 'ar-condicionado', 'vacuo', 'A leitura do vácuo sobe um pouco e estabiliza alta. O que fazer?', array['Quebrar o vácuo com nitrogênio e refazer', 'Está ótimo, pode abrir as válvulas e liberar o gás', 'Trocar a tubulação inteira, que está furada', 'Completar com fluido para empurrar a umidade para fora']::text[], 'Estabilizar numa faixa alta indica umidade. O manual manda circular nitrogênio e refazer o vácuo.', 'Manual Midea Springer', true, now()),
  ('ar-14', 'ar-condicionado', 'vacuo', 'Depois de atingir o vácuo, quanto tempo esperar observando a leitura?', array['Pelo menos 20 minutos', 'Nada, pode abrir as válvulas assim que atingir a faixa', 'Uns 10 segundos, só para ver se o ponteiro parou', 'Até o dia seguinte']::text[], 'O manual indica tempo mínimo de 20 minutos para estabilização, para confirmar sistema seco e sem fuga.', 'Manual Midea Springer', true, now()),
  ('ar-15', 'ar-condicionado', 'vacuo', 'O que fazer de tempos em tempos com a bomba de vácuo?', array['Trocar o óleo', 'Nada, bomba de vácuo não tem manutenção', 'Lavar por dentro com água e deixar secar', 'Encher de fluido refrigerante para não ressecar']::text[], 'Óleo velho e úmido tira a capacidade da bomba de chegar ao vácuo certo.', 'Manual Midea Springer', true, now()),
  ('ar-16', 'ar-condicionado', 'carga', 'Split que vem carregado para 7,5 m de tubulação, instalado com 5 m. E a carga de fluido?', array['Não deve ser alterada', 'Precisa completar um pouco de gás', 'Precisa tirar um pouco de gás', 'Tem que recarregar do zero']::text[], 'O manual é claro: até o comprimento da carga de fábrica, a carga NÃO DEVE SER ALTERADA. Completar sem necessidade deixa excesso de fluido.', 'Manual Midea Springer', true, now()),
  ('ar-17', 'ar-condicionado', 'carga', 'A tubulação ficou com 10 m, e a carga de fábrica cobre 7,5 m. O que fazer?', array['Adicionar os gramas por metro da tabela', 'Nada, a diferença de comprimento é pequena', 'Encher até o manômetro marcar a mesma pressão de outro aparelho', 'Dobrar a carga para compensar a distância']::text[], 'Para cada metro acima do comprimento da carga de fábrica, o manual indica quantos gramas adicionar, e o valor muda por modelo.', 'Manual Midea Springer', true, now()),
  ('ar-18', 'ar-condicionado', 'carga', 'Na carga de R-410A, como o fluido deve sair do cilindro?', array['Líquido, controlado na balança', 'Gás, com o cilindro em pé, para não entrar líquido', 'Tanto faz', 'Aos poucos, até o tubo de sucção começar a suar']::text[], 'O manual pede fluido saindo líquido e carga controlada até a quantidade ideal, com balança. O R-410A é uma mistura, e carregado como gás muda a proporção.', 'Manual Midea Springer', true, now()),
  ('ar-19', 'ar-condicionado', 'carga', 'Antes de ligar o aparelho pela primeira vez, depois do vácuo e da carga, o que falta?', array['Abrir as válvulas de serviço', 'Nada, pode ligar direto no modo refrigerar', 'Tirar o filtro da evaporadora para o ar passar melhor', 'Ligar no modo turbo para o gás circular mais rápido']::text[], 'O manual proíbe pôr em funcionamento sem as válvulas abertas, porque o compressor se danifica.', 'Manual Midea Springer', true, now()),
  ('ar-20', 'ar-condicionado', 'carga', 'Numa recarga completa, quanto tempo o sistema pode ficar aberto para o ar?', array['No máximo uns 5 minutos', 'Pode ficar aberto o dia todo', 'Até o fim do serviço', 'Uma hora']::text[], 'Aberto, o sistema puxa umidade do ar. O manual limita a exposição a 5 minutos.', 'Manual Midea Springer', true, now()),
  ('ar-21', 'ar-condicionado', 'carga', 'Um aparelho de R-410A está com pouco gás e você só tem R-22. O que fazer?', array['Não completar: não se mistura fluido', 'Completar com R-22, que funciona igual no compressor', 'Misturar meio a meio para equilibrar a pressão', 'Completar com R-22 e trocar o óleo do compressor depois']::text[], 'Cada fluido tem pressão e óleo próprios. Misturar estraga o sistema e o fluido não pode mais ser reaproveitado.', 'ABRAVA', true, now()),
  ('ar-22', 'ar-condicionado', 'carga', 'Dá para usar o mesmo manifold de R-22 num aparelho de R-410A?', array['Não: pressão maior e conexão diferente', 'Sim, todo manifold serve para todos os fluidos', 'Sim, desde que troque só as mangueiras por novas', 'Sim, se zerar os manômetros antes de conectar']::text[], 'O R-410A tem pressões mais altas e rosca de serviço própria (1/2 in no manual). Ferramenta errada pode estourar ou contaminar.', 'Manual Midea Springer', true, now()),
  ('ar-23', 'ar-condicionado', 'seguranca', 'Para tirar o fluido de um aparelho na manutenção, como fazer?', array['Recolhedora e cilindro próprio', 'Abrir a válvula e deixar sair num lugar ventilado', 'Recolher usando o compressor da própria unidade', 'Furar o tubo em local aberto']::text[], 'O fabricante pede bomba recolhedora e cilindro apropriado. Soltar fluido no ar polui e desperdiça o fluido.', 'Manual Midea Springer', true, now()),
  ('ar-24', 'ar-condicionado', 'seguranca', 'O que muda ao instalar um aparelho com fluido R-32?', array['É levemente inflamável: sem chama e com ferramentas próprias', 'Nada, ele é igual ao R-22 em tudo', 'Ele é tóxico ao toque e exige roupa especial', 'Ele dispensa vácuo porque não absorve umidade']::text[], 'O R-32 é classe A2L, levemente inflamável. Pede cuidado com chama e bomba de vácuo compatível.', 'ABRAVA / LG', true, now()),
  ('ar-25', 'ar-condicionado', 'dreno', 'Como deve ficar a mangueira do dreno?', array['Sempre descendo, sem barriga', 'Pode subir um pouco e depois descer até a saída', 'Reta, sem caimento, para não ficar aparente', 'Enrolada atrás da evaporadora para ocupar menos espaço']::text[], 'A drenagem é por gravidade. Qualquer subida ou barriga acumula água e faz voltar para dentro.', 'Manual Midea Springer', true, now()),
  ('ar-26', 'ar-condicionado', 'dreno', 'Onde não pode ficar a ponta da mangueira do dreno?', array['Mergulhada em água', 'Num ralo do lado de fora da casa', 'Numa tubulação de dreno própria do prédio', 'Numa área externa com piso e caimento']::text[], 'Com a ponta submersa, a água não escoa e volta pela evaporadora.', 'Manual Midea Springer', true, now()),
  ('ar-27', 'ar-condicionado', 'diagnostico', 'A evaporadora está pingando dentro do quarto. O que verificar primeiro?', array['Dreno entupido ou sem caimento, e o nível da unidade', 'Se falta gás, porque o gelo derrete e pinga', 'Se o controle remoto está com a pilha fraca', 'Se a tomada é de 20 A e o disjuntor é próprio']::text[], 'O manual pede conferir a inclinação do dreno e o nível da unidade. É a causa mais comum de água vazando para dentro.', 'Manual Midea Springer', true, now()),
  ('ar-28', 'ar-condicionado', 'eletrica', 'Como deve ser a alimentação elétrica do split?', array['Circuito independente com disjuntor', 'Na tomada mais próxima', 'No mesmo circuito do chuveiro', 'Com extensão reforçada']::text[], 'O manual pede circuito independente com disjuntor, conforme a NBR 5410. Circuito sobrecarregado derruba a tensão e o compressor não parte.', 'Manual Midea Springer', true, now()),
  ('ar-29', 'ar-condicionado', 'eletrica', 'Aparelho de 220 V. Você mede 185 V na alimentação. O que fazer?', array['Não ligar e avisar: está abaixo de 198 V', 'Ligar normal, a diferença de tensão é pequena', 'Ligar no modo turbo para compensar a tensão baixa', 'Trocar o capacitor, que é o que sofre com tensão baixa']::text[], 'O manual aceita de 90% a 110% da tensão nominal. Abaixo disso, o compressor sofre e pode queimar.', 'Manual Midea Springer', true, now()),
  ('ar-30', 'ar-condicionado', 'eletrica', 'O aparelho precisa de aterramento?', array['Sim, sempre', 'Não, a carcaça da evaporadora é de plástico', 'Só se o aparelho for de 220 V', 'Só se o cliente pedir ou se for área úmida']::text[], 'As ligações seguem a NBR 5410, e o manual indica por onde fazer o aterramento. A condensadora é metálica e fica exposta.', 'Manual Midea Springer', true, now()),
  ('ar-31', 'ar-condicionado', 'instalacao', 'Ao escolher o lugar da condensadora, o que respeitar?', array['Os espaços mínimos do manual', 'Encostar na parede', 'Dentro de um nicho fechado', 'Com a saída de ar virada para a parede, por causa do barulho']::text[], 'Sem espaço, a condensadora recircula o ar quente e perde rendimento. O espaço também permite o reparo.', 'Manual Midea Springer', true, now()),
  ('ar-32', 'ar-condicionado', 'instalacao', 'Como transportar a condensadora até o local?', array['Em pé, pouco inclinada', 'Deitada, que é mais seguro no carro', 'De lado, com as válvulas para cima', 'Tanto faz']::text[], 'O manual pede não inclinar mais de 15° em relação à vertical, para não deslocar o óleo do compressor.', 'Manual Midea Springer', true, now()),
  ('ar-33', 'ar-condicionado', 'instalacao', 'Qual limite de tubulação respeitar entre evaporadora e condensadora?', array['O comprimento e o desnível do manual', 'Nenhum, se carregar mais gás no fim', 'No máximo 1 metro em qualquer aparelho', 'Pelo menos 20 metros, para o gás esfriar']::text[], 'Cada modelo tem comprimento equivalente e desnível máximos. Passar disso prejudica o retorno de óleo e o rendimento.', 'Manual Midea Springer', true, now()),
  ('ar-34', 'ar-condicionado', 'instalacao', 'Para que limpar as linhas com nitrogênio antes de conectar?', array['Tirar a sujeira da obra', 'Resfriar o tubo antes de conectar as porcas', 'Testar se o tubo é de cobre de verdade', 'Não serve para nada']::text[], 'O manual diz que a limpeza com nitrogênio evita que a sujeira da obra fique na tubulação.', 'Manual Midea Springer', true, now()),
  ('ar-35', 'ar-condicionado', 'instalacao', 'A tubulação está vibrando e fazendo barulho. O que o manual sugere?', array['Fazer loops ou usar flexíveis', 'Apertar mais as porcas flange das duas pontas', 'Colocar mais gás para a pressão segurar o tubo', 'Encher a passagem da parede com espuma expansiva']::text[], 'Loops ou flexíveis absorvem a vibração. A tubulação deve ficar presa em suportes.', 'Manual Midea Springer', true, now()),
  ('ar-36', 'ar-condicionado', 'diagnostico', 'O aparelho liga, mas o ambiente não gela. O que verificar antes de pensar em gás?', array['Sujeira, tamanho do aparelho e válvulas', 'Trocar o compressor', 'Completar gás até a tubulação gelar', 'Trocar o controle remoto e a placa receptora']::text[], 'O manual lista sujeira nas serpentinas, aparelho pequeno para o ambiente e válvula fechada antes de vazamento.', 'Manual Midea Springer', true, now()),
  ('ar-37', 'ar-condicionado', 'diagnostico', 'A evaporadora está fazendo gelo. Quais são as causas indicadas pelo fabricante?', array['Filtro ou capilar obstruído, ou vazamento', 'Excesso de óleo na bomba de vácuo usada na instalação', 'Tomada de 10 A, que limita a corrente do compressor', 'Controle remoto no modo desumidificar']::text[], 'Obstrução no filtro ou capilar e falta de fluido por vazamento são as causas listadas para o evaporador bloqueado com gelo.', 'Manual Midea Springer', true, now()),
  ('ar-38', 'ar-condicionado', 'diagnostico', 'O compressor não parte e o cliente usa o aparelho num benjamim com outros aparelhos. O que fazer?', array['Ligar num ponto exclusivo', 'Trocar o compressor', 'Completar gás para o compressor partir', 'Trocar o controle remoto e testar de novo']::text[], 'Circuito sobrecarregado derruba a tensão. O manual pede tomada única e exclusiva.', 'Manual Midea Springer', true, now()),
  ('ar-39', 'ar-condicionado', 'manutencao', 'Qual manutenção o próprio usuário deve fazer com frequência?', array['Limpar o filtro de ar', 'Completar o gás uma vez por ano', 'Abrir a condensadora e lavar a placa eletrônica', 'Trocar o capacitor de tempos em tempos']::text[], 'O filtro é a manutenção do dia a dia. Filtro sujo reduz o ar e pode até congelar o evaporador.', 'Manual Midea Springer', true, now()),
  ('ar-40', 'ar-condicionado', 'manutencao', 'Em escritórios, academias e lojas abertas ao público, o que a lei exige dos aparelhos?', array['Um PMOC', 'Nada, a lei vale só para hospitais', 'Trocar os aparelhos a cada 2 anos', 'Guardar a nota fiscal da instalação']::text[], 'A Lei 13.589/2018 obriga edifícios de uso público e coletivo climatizados a ter PMOC.', 'Lei 13.589/2018', true, now())
insert into public.quiz_tests (service_id, label, draw, pass, minutes) values ('cameras', 'Câmeras de segurança', 15, 11, 15)
insert into private.quiz_questions (id, service_id, topic, question, options, why, source, active, updated_at) values
  ('cam-01', 'cameras', 'gravador', 'Como deve estar o gravador (DVR) na hora de ligar os cabos das câmeras atrás dele?', array['Desligado', 'Ligado, para já ver a imagem aparecer', 'Ligado, mas com o monitor desligado', 'Tanto faz, os conectores são de baixa tensão']::text[], 'O fabricante avisa que conectar com o DVR ligado pode queimar as entradas e as saídas e tira a garantia.', 'Manual Intelbras', true, now()),
  ('cam-02', 'cameras', 'gravador', 'Quando ligar o DVR na tomada pela primeira vez?', array['Só depois de completar a instalação', 'Antes de tudo', 'Depois de instalar só a primeira câmera', 'Assim que tirar da caixa, para testar']::text[], 'O manual pede não energizar o DVR antes de completar a instalação.', 'Manual Intelbras', true, now()),
  ('cam-03', 'cameras', 'gravador', 'Onde instalar o DVR?', array['Em lugar seco e fresco, sem tapar a ventilação', 'Dentro de um armário fechado', 'Em cima do roteador, para ficar perto da internet', 'Na garagem']::text[], 'O manual pede ambiente frio e seco, longe de calor e de sol direto, sem objetos em cima e sem bloquear as aberturas de ventilação.', 'Manual Intelbras', true, now()),
  ('cam-04', 'cameras', 'gravador', 'O que o manual do DVR exige da instalação elétrica?', array['Aterramento conforme a NBR 5410', 'Nada, porque o gravador funciona com fonte de 12 V', 'Só um estabilizador', 'Uma tomada de 20 A exclusiva']::text[], 'Mesmo com fonte, o fabricante pede o aparelho ligado a um sistema de aterramento conforme a NBR 5410 e alerta para o risco de incêndio com tomadas sobrecarregadas.', 'Manual Intelbras', true, now()),
  ('cam-05', 'cameras', 'gravador', 'Vai instalar o HD dentro do DVR. Como fazer?', array['Com o DVR desligado', 'Com o DVR ligado, para ele reconhecer na hora', 'Com o DVR em modo de gravação', 'Com o DVR ligado e o cabo de rede tirado']::text[], 'O manual pede o DVR desligado para colocar o HD, senão os componentes podem queimar.', 'Manual Intelbras', true, now()),
  ('cam-06', 'cameras', 'seguranca', 'No primeiro acesso, o DVR pede para criar a senha do administrador. Qual senha usar?', array['Uma senha forte, combinada com o cliente', '123456, que o cliente consegue lembrar com facilidade', 'A mesma senha que você usa em todos os clientes, para dar suporte', 'O número da casa do cliente com o ano de nascimento']::text[], 'Câmera com senha fraca ou repetida pode ser invadida pela internet. O manual pede uma senha de 8 a 32 caracteres.', 'Manual Intelbras', true, now()),
  ('cam-07', 'cameras', 'seguranca', 'O que configurar logo depois da senha do DVR?', array['E-mail ou perguntas de recuperação', 'O papel de parede e o idioma da tela do gravador', 'O volume do alarme e o som das teclas do mouse', 'Nada, porque o técnico reseta a senha quando precisar']::text[], 'Na Intelbras não é permitido resetar a senha do administrador. Se o cliente esquecer, a recuperação depende do e-mail ou das perguntas cadastradas.', 'Manual Intelbras', true, now()),
  ('cam-08', 'cameras', 'seguranca', 'E o firmware (sistema) do gravador e das câmeras?', array['Manter atualizado pelo site do fabricante', 'Nunca atualizar', 'Atualizar com arquivos de fóruns', 'Atualizar só quando a imagem de alguma câmera sumir']::text[], 'O fabricante publica atualizações no site. Elas corrigem falhas, inclusive de segurança.', 'Manual Intelbras', true, now()),
  ('cam-09', 'cameras', 'cabos', 'Qual cabo coaxial usar numa câmera HD (HDCVI) para não ter problema de imagem?', array['Coaxial com 85% ou mais de cobre, homologado', 'Qualquer coaxial de antena de TV, que é o mais barato', 'Cabo de som blindado, que é mais fino e fácil de passar', 'Fio paralelo de luz, que já tem dois condutores']::text[], 'O manual pede cabo com no mínimo 85% de cobre e malha de cobre. Cabo de liga barata dá chuvisco e perde imagem.', 'Manual Intelbras', true, now()),
  ('cam-10', 'cameras', 'cabos', 'Vai usar cabo de rede (UTP) em vez de coaxial nas câmeras HDCVI. O que precisa?', array['Balun passivo nas duas pontas', 'Balun ativo', 'Conversor de fibra comum no meio do caminho', 'Nada, é só emendar o UTP direto no conector da câmera']::text[], 'O fabricante indica balun passivo. Balun ativo e conversor de mídia comum distorcem o sinal HD.', 'Manual Intelbras', true, now()),
  ('cam-11', 'cameras', 'diagnostico', 'A imagem de uma câmera aparece com chuvisco e listras. O que verificar primeiro?', array['Conectores, emendas e cabo', 'A senha do DVR', 'O tamanho do HD', 'A data e a hora do gravador, que podem estar erradas']::text[], 'O manual aponta conectores e emendas ruins como causa de ruído e interferência na imagem.', 'Manual Intelbras', true, now()),
  ('cam-12', 'cameras', 'instalacao', 'A câmera vai ficar na fachada, pegando chuva. O que conferir no modelo?', array['Se é para área externa (ex.: IP66)', 'Só a resolução', 'Se a cor combina com a fachada para não chamar atenção', 'Se é a mais barata']::text[], 'Câmera de área interna não aguenta chuva. Para área externa, o modelo precisa ter grau de proteção indicado, como IP66.', 'Manual Intelbras', true, now()),
  ('cam-13', 'cameras', 'instalacao', 'Onde deixar a fonte de energia de uma câmera externa?', array['Em área coberta ou caixa hermética', 'Pendurada no próprio cabo, do lado de fora da parede', 'Enterrada no jardim, protegida dentro de um saco plástico', 'Enrolada em fita isolante, que impede a água de entrar']::text[], 'A câmera pode ser à prova d''água, mas a fonte normalmente não é. Fonte molhada queima e dá curto.', 'Manual Intelbras', true, now()),
  ('cam-14', 'cameras', 'instalacao', 'Por que evitar apontar a câmera para árvores e arbustos que balançam?', array['Atrapalham a imagem e disparam gravações à toa', 'Porque as folhas encostam e riscam a lente da câmera', 'Porque o verde das folhas estraga o sensor de imagem', 'Não há motivo técnico']::text[], 'O manual da Intelbras pede evitar folhagens em movimento: atrapalham a visão e fazem a câmera gravar e alertar à toa.', 'Manual Intelbras', true, now()),
  ('cam-15', 'cameras', 'instalacao', 'A câmera foi instalada virada para o sol da tarde ou para uma lâmpada forte. O que acontece?', array['A imagem fica escura ou estourada', 'A imagem fica mais nítida', 'A câmera grava por mais tempo sem precisar de HD', 'Nada muda']::text[], 'Contra a luz, o sensor não equilibra claro e escuro, e o rosto de quem passa fica escuro. Escolha um ângulo com a luz atrás ou de lado.', 'Prática de campo', true, now()),
  ('cam-16', 'cameras', 'instalacao', 'O cliente quer a câmera dentro de casa, filmando a rua pelo vidro da janela. O que avisar?', array['À noite o infravermelho reflete no vidro', 'Que o vidro protege e melhora a imagem durante a noite', 'Que basta limpar bem o vidro uma vez por semana', 'Que funciona igual a uma câmera externa']::text[], 'A luz infravermelha da câmera bate no vidro e volta para a lente. De noite, a imagem fica só reflexo.', 'Prática de campo', true, now()),
  ('cam-17', 'cameras', 'wifi', 'A câmera Wi-Fi não aparece no aplicativo na hora de adicionar. O que verificar primeiro?', array['Se o celular está numa rede Wi-Fi de 2,4 GHz', 'Se o celular está na rede de 5 GHz, que é mais rápida', 'Se a câmera está com a lente limpa', 'Se o celular está no modo avião']::text[], 'As câmeras Mibo, como muitas outras, só funcionam em 2,4 GHz. Pela rede de 5 GHz não dá para adicionar.', 'Intelbras Mibo', true, now()),
  ('cam-18', 'cameras', 'wifi', 'O roteador usa o mesmo nome para as redes de 2,4 e 5 GHz, e a câmera não conecta. O que fazer?', array['Separar os nomes das redes', 'Desligar a rede de 2,4 GHz para forçar a de 5 GHz', 'Trocar a câmera por outra marca, porque é incompatível', 'Colocar a câmera mais longe do roteador para não interferir']::text[], 'Os fabricantes recomendam nomes diferentes para cada faixa, para o celular ficar na de 2,4 GHz durante a configuração.', 'Intelbras Mibo', true, now()),
  ('cam-19', 'cameras', 'seguranca', 'A etiqueta da câmera Wi-Fi tem uma chave de acesso. O que fazer com ela?', array['Entregar ao cliente para guardar', 'Anotar no seu caderno de clientes para dar suporte depois', 'Colar na parede ao lado da câmera para não perder', 'Jogar fora junto com a caixa']::text[], 'A chave é a senha de criptografia das imagens e permite ver as câmeras de outro celular. Ela é do cliente.', 'Intelbras Mibo', true, now()),
  ('cam-20', 'cameras', 'seguranca', 'Terminado o serviço, de quem devem ser a conta do aplicativo e as senhas?', array['Do cliente', 'Suas, para dar suporte depois sem precisar pedir senha', 'Do vizinho, que indicou o serviço e vai acompanhar', 'Da loja que vendeu a câmera, por causa da garantia']::text[], 'Quem tem a conta vê as imagens da casa. Ficar com acesso depois do serviço expõe o cliente e você.', 'Prática de campo', true, now()),
  ('cam-21', 'cameras', 'privacidade', 'A câmera do portão está pegando a janela do vizinho. O que fazer?', array['Ajustar o ângulo ou usar máscara de privacidade', 'Deixar assim, porque a câmera é do cliente e está no imóvel dele', 'Aumentar o zoom na janela para identificar quem mora lá', 'Avisar o vizinho por escrito e deixar gravando do mesmo jeito']::text[], 'A captação deve se limitar ao necessário para proteger o imóvel. Os gravadores têm máscara de privacidade para cobrir áreas da imagem.', 'LGPD em condomínio', true, now()),
  ('cam-22', 'cameras', 'privacidade', 'O síndico quer câmeras nas áreas comuns do prédio. O que é necessário?', array['Aprovação em assembleia e aviso aos moradores', 'Só a decisão do síndico', 'Autorização da delegacia de polícia do bairro', 'Nada, porque área comum pode ser filmada à vontade']::text[], 'A instalação em áreas comuns depende de aprovação em assembleia, registrada em ata, e de comunicação clara aos moradores.', 'LGPD em condomínio', true, now()),
  ('cam-23', 'cameras', 'privacidade', 'Um morador quer uma câmera no corredor apontada para a porta do vizinho. O que você faz?', array['Filmar só a própria porta', 'Instalo como ele pediu', 'Instalo escondida num vaso, para não gerar briga', 'Instalo com áudio']::text[], 'Mesmo em área privativa, a câmera não deve registrar corredores nem portas de outros imóveis. Senão o morador pode ser obrigado a retirá-la.', 'LGPD em condomínio', true, now()),
  ('cam-24', 'cameras', 'privacidade', 'A câmera tem opção de gravar áudio. O que considerar?', array['Gravar conversa é mais sensível que imagem', 'Que o áudio deve ficar sempre ligado para servir de prova', 'Que áudio não conta como dado pessoal', 'Que ligar o áudio melhora a qualidade da imagem']::text[], 'Captar imagem já é tratar dado pessoal. Gravar voz vai além, porque conversas revelam muito mais sobre as pessoas.', 'LGPD em condomínio', true, now()),
  ('cam-25', 'cameras', 'seguranca', 'A câmera vai ficar a 4 metros de altura no muro. Que regra vale?', array['A NR-35, de trabalho em altura', 'Nenhuma, porque é só a instalação de uma câmera pequena', 'Só as instruções do fabricante da câmera', 'Só vale alguma regra acima de 10 metros de altura']::text[], 'A NR-35 trata como trabalho em altura toda atividade acima de 2 m do nível inferior com risco de queda.', 'NR-35', true, now()),
  ('cam-26', 'cameras', 'seguranca', 'Precisa puxar energia de uma caixa de tomada para alimentar a câmera. Qual é o cuidado?', array['Desligar o disjuntor e testar se não há tensão', 'Mexer com a tomada ligada, com cuidado e luva comum', 'Fazer as emendas só com fita crepe', 'Ligar direto na fiação da parede, sem usar caixa']::text[], 'Mexer em circuito elétrico pede desligar e confirmar a ausência de tensão. Se o serviço for além disso, é trabalho de eletricista.', 'NR-10', true, now()),
  ('cam-27', 'cameras', 'gravador', 'Como escolher o tamanho do HD do gravador?', array['Câmeras, resolução e dias de gravação', 'O maior HD que couber no gravador, sempre', 'O menor possível', 'Tanto faz']::text[], 'Os dias de gravação dependem de quantas câmeras, de qual resolução e do modo de gravação. O fabricante tem calculadora de HD.', 'Manual Intelbras', true, now()),
  ('cam-28', 'cameras', 'seguranca', 'O cliente quer ver as câmeras pelo celular fora de casa. Qual é o jeito mais seguro?', array['Pelo app oficial, com senha forte', 'Abrindo portas no roteador e deixando a senha padrão', 'Compartilhando a senha num grupo de mensagens da família', 'Por um aplicativo genérico de outra loja, que é mais leve']::text[], 'Abrir portas do roteador e deixar senha padrão facilita invasão. O app oficial com senha forte é o caminho indicado.', 'CERT.br', true, now()),
  ('cam-29', 'cameras', 'gravador', 'Qual cabo HDMI usar entre o DVR e o monitor?', array['Certificado, de até uns 5 metros', 'Qualquer um, mesmo com 20 metros, se for grosso', 'Cabo de rede com um adaptador barato de HDMI', 'Dois cabos HDMI emendados com fita isolante']::text[], 'O manual pede cabo HDMI certificado e recomenda no máximo 5 metros para não ter problema de imagem.', 'Manual Intelbras', true, now()),
  ('cam-30', 'cameras', 'gravador', 'Como limpar o gravador?', array['Desligado da tomada, com pano seco', 'Com pano molhado e detergente', 'Com spray de limpeza direto nas aberturas', 'Ligado, para não perder a gravação']::text[], 'O manual pede desligar da tomada e usar só pano seco, sem detergente líquido ou em aerossol.', 'Manual Intelbras', true, now())
insert into public.quiz_tests (service_id, label, draw, pass, minutes) values ('casa-inteligente', 'Casa inteligente', 15, 11, 15)
insert into private.quiz_questions (id, service_id, topic, question, options, why, source, active, updated_at) values
  ('cas-01', 'casa-inteligente', 'eletrica', 'Vai trocar o interruptor comum por um interruptor inteligente. O que fazer antes de tirar o espelho?', array['Desligar o disjuntor do circuito', 'Só apagar a luz no interruptor antigo', 'Usar luva de borracha e fazer ligado', 'Desligar o Wi-Fi da casa']::text[], 'O fabricante pede desligar os disjuntores do local antes de começar e fazer todas as ligações com a energia desligada.', 'Manual Intelbras', true, now()),
  ('cas-02', 'casa-inteligente', 'eletrica', 'O interruptor inteligente pede fio neutro. Qual neutro ligar nele?', array['O neutro das lâmpadas desse circuito', 'Qualquer neutro da casa', 'O fio terra, quando a caixa não tiver neutro', 'Nenhum, porque basta ligar a fase e o retorno']::text[], 'O manual diz que o neutro ligado ao produto deve ser o mesmo conectado às lâmpadas. Neutro de outro circuito causa falha e desarme.', 'Manual Intelbras', true, now()),
  ('cas-03', 'casa-inteligente', 'eletrica', 'Em que caixa o fabricante recomenda instalar o interruptor inteligente?', array['Uma caixa 4×2 só para ele', 'Na caixa cheia de emendas de outros circuitos, para aproveitar', 'Dentro do quadro de disjuntores, junto com os outros', 'Solto fora da caixa']::text[], 'O manual recomenda a caixa 4×2 sem outros fios. O módulo é grande e esquenta, e emendas apertadas dão mau contato.', 'Manual Intelbras', true, now()),
  ('cas-04', 'casa-inteligente', 'eletrica', 'Antes de religar a energia, o que conferir?', array['Ligações certas e nada vivo exposto', 'Só se o Wi-Fi da casa está ligado e com internet', 'Se o aplicativo já está instalado no celular do cliente', 'Nada, porque se ligar errado ele desliga sozinho']::text[], 'O fabricante pede verificar as conexões e isolar todas as partes vivas para evitar curto-circuito.', 'Manual Intelbras', true, now()),
  ('cas-05', 'casa-inteligente', 'eletrica', 'O interruptor inteligente aguenta 10 A (1.270 W em 127 V). O cliente quer ligar nele um lustre de 1.800 W em 127 V. E agora?', array['Não pode: passa do limite', 'Pode, porque o limite do manual é só de referência', 'Pode, desde que troque por lâmpadas de LED depois', 'Pode, desde que o disjuntor do circuito seja maior']::text[], 'A carga controlada precisa respeitar a potência máxima do produto: 1.270 W em 127 V ou 2.200 W em 220 V.', 'Manual Intelbras', true, now()),
  ('cas-06', 'casa-inteligente', 'eletrica', 'As lâmpadas de LED do circuito ficam piscando com o interruptor inteligente. O que o fabricante orienta?', array['Lâmpadas com fator de potência ≥ 0,7', 'Trocar por lâmpadas mais baratas e de menor potência', 'Ligar o neutro no fio terra para estabilizar', 'Diminuir a potência do disjuntor do circuito']::text[], 'O manual recomenda lâmpadas com fator de potência igual ou superior a 0,7. Lâmpadas fora disso dão problema no circuito.', 'Manual Intelbras', true, now()),
  ('cas-07', 'casa-inteligente', 'eletrica', 'Onde não instalar o interruptor ou a tomada inteligente?', array['Em local úmido ou com vento do ar', 'Na sala, porque tem muita gente passando', 'No quarto', 'Numa parede interna e seca']::text[], 'O manual pede ambiente interno, seco, sem vibração e longe de calor ou vento.', 'Manual Intelbras', true, now()),
  ('cas-08', 'casa-inteligente', 'eletrica', 'Não se sente seguro para fazer a ligação elétrica de um módulo inteligente. O que fazer?', array['Chamar um eletricista', 'Fazer assim mesmo', 'Ligar só a fase primeiro e ver o que acontece', 'Pedir para o próprio cliente fazer a ligação']::text[], 'O próprio manual orienta procurar um eletricista qualificado quando a pessoa não se sente confiante.', 'Manual Intelbras', true, now()),
  ('cas-09', 'casa-inteligente', 'rede', 'Em qual rede Wi-Fi a maioria dos dispositivos inteligentes funciona?', array['2,4 GHz', 'Só 5 GHz', 'Qualquer uma, eles escolhem sozinhos', 'Só na rede de convidados de 5 GHz']::text[], 'Os manuais dizem que os dispositivos funcionam só na frequência de 2,4 GHz.', 'Manual Intelbras', true, now()),
  ('cas-10', 'casa-inteligente', 'rede', 'O roteador do cliente é dual band com o mesmo nome nas duas redes. O que o fabricante recomenda?', array['Nomes diferentes para cada rede', 'Desligar a rede de 2,4 GHz para forçar a de 5 GHz', 'Trocar o roteador por um que só tenha 5 GHz', 'Deixar assim e tentar o pareamento várias vezes']::text[], 'Com nome unificado, o celular pode ficar na faixa de 5 GHz e o pareamento falha. Nomes separados facilitam a configuração.', 'Manual Intelbras', true, now()),
  ('cas-11', 'casa-inteligente', 'rede', 'O interruptor vai ficar a 30 metros do roteador, com várias paredes. O que fazer?', array['Repetidor ou mesh perto do local', 'Instalar assim', 'Aumentar a potência no app do roteador ao máximo', 'Ligar um cabo de rede direto no interruptor']::text[], 'O manual indica distância de 15 a 20 m sem obstáculos. Longe disso, o dispositivo perde a conexão.', 'Manual Intelbras', true, now()),
  ('cas-12', 'casa-inteligente', 'rede', 'Com 30 dispositivos instalados, as automações começam a falhar. O que verificar?', array['A capacidade e a estabilidade da rede', 'Se as lâmpadas da casa são todas da mesma cor', 'Se o aplicativo está no modo escuro ou claro', 'Se o disjuntor do circuito é de 20 A']::text[], 'Os manuais avisam que instabilidade da rede causa falha nas automações e pedem rede que suporte a quantidade de dispositivos.', 'Manual Intelbras', true, now()),
  ('cas-13', 'casa-inteligente', 'rede', 'Para parear um interruptor inteligente pelo app, como deve estar o celular?', array['Bluetooth ligado e Wi-Fi 2,4 GHz', 'No modo avião, para não ter interferência', 'Só nos dados móveis, sem Wi-Fi ligado', 'Na rede de 5 GHz, com o Bluetooth desligado']::text[], 'O manual pede Bluetooth ativo e o celular conectado à rede de 2,4 GHz com acesso à internet.', 'Manual Intelbras', true, now()),
  ('cas-14', 'casa-inteligente', 'tomada', 'Uma tomada inteligente de 10 A em 127 V aguenta quanto?', array['Até uns 1.270 W no total', 'Até 5.000 W', 'Qualquer aparelho que caiba no plugue', 'Só celular']::text[], 'Corrente vezes tensão: 10 A × 127 V = 1.270 W. Em 220 V, são 2.200 W.', 'Manual Intelbras', true, now()),
  ('cas-15', 'casa-inteligente', 'tomada', 'O cliente quer ligar um aquecedor de 2.000 W em 127 V numa tomada inteligente de 10 A. O que você diz?', array['Não dá: puxa uns 16 A', 'Que dá, porque é só por algumas horas por dia', 'Que dá, desde que use um benjamim de qualidade', 'Que dá, porque a tomada é nova e aguenta']::text[], '2.000 W ÷ 127 V ≈ 16 A, bem acima dos 10 A da tomada.', 'Manual Intelbras', true, now()),
  ('cas-16', 'casa-inteligente', 'tomada', 'Num filtro de linha inteligente de 10 A com várias tomadas, como calcular a carga?', array['Somar tudo o que liga junto, até 10 A', 'Cada tomada do filtro aguenta 10 A sozinha', 'Só conta o aparelho mais forte que estiver ligado', 'Não precisa calcular']::text[], 'O limite é da corrente total. Acima dele, o produto desliga para se proteger, e é preciso tirar aparelhos antes de religar.', 'Manual Intelbras', true, now()),
  ('cas-17', 'casa-inteligente', 'tomada', 'O cliente pergunta se dá para ligar o chuveiro elétrico numa tomada inteligente para controlar pelo celular. O que dizer?', array['Não: chuveiro não usa tomada', 'Que dá, desde que seja uma tomada inteligente de 20 A', 'Que dá, usando uma extensão de fio grosso', 'Que dá, se o chuveiro ficar só na posição verão']::text[], 'O fabricante proíbe plugue ou tomada no chuveiro, e um chuveiro puxa mais de 30 A.', 'Manual Lorenzetti', true, now()),
  ('cas-18', 'casa-inteligente', 'contas', 'Em nome de quem criar a conta do aplicativo da casa inteligente?', array['Do cliente, com o e-mail dele', 'Do técnico', 'Da loja que vendeu os produtos', 'Uma conta compartilhada entre seus clientes']::text[], 'Quem tem a conta controla a casa: luzes, fechaduras, câmeras. A conta tem que ser do cliente.', 'Prática de campo', true, now()),
  ('cas-19', 'casa-inteligente', 'contas', 'Além da senha, o que ativar na conta Amazon ou Google do cliente?', array['Verificação em duas etapas', 'Login automático em todos os aparelhos', 'Senha curta para lembrar', 'Compartilhamento público da casa']::text[], 'O CERT.br orienta reforçar a senha com outra forma de autenticação, porque só a senha não basta.', 'CERT.br', true, now()),
  ('cas-20', 'casa-inteligente', 'contas', 'E a senha do roteador e do Wi-Fi da casa automatizada?', array['Trocar as senhas padrão por senhas fortes', 'Manter a de fábrica, que vem impressa', 'Deixar a rede aberta para os dispositivos conectarem fácil', 'Usar o nome do cliente']::text[], 'Senha padrão pode ser descoberta. Quem entra na rede pode chegar aos dispositivos da casa.', 'CERT.br', true, now()),
  ('cas-21', 'casa-inteligente', 'contas', 'O que fazer com as atualizações dos dispositivos e do roteador?', array['Atualização automática ativada', 'Bloquear as atualizações para nada mudar sozinho', 'Atualizar só quando algum aparelho parar de funcionar', 'Nada, porque dispositivo inteligente não recebe atualização']::text[], 'Atualizações corrigem falhas de segurança. O CERT.br pede ativar a atualização automática sempre que possível.', 'CERT.br', true, now()),
  ('cas-22', 'casa-inteligente', 'assistente', 'A Alexa está com a luz vermelha acesa direto. O que isso significa na maioria das vezes?', array['Microfone desligado no botão', 'A Alexa está com defeito e precisa de assistência', 'A Alexa está gravando tudo o que se fala na sala', 'A bateria interna acabou e precisa carregar']::text[], 'A luz vermelha fixa indica microfone desligado: ela não está ouvindo. Basta apertar o botão de novo.', 'Amazon Echo', true, now()),
  ('cas-23', 'casa-inteligente', 'assistente', 'O cliente tem medo de a Alexa ouvir conversas. O que mostrar a ele?', array['O botão do microfone e a privacidade no app', 'Que não tem o que fazer', 'Que é só tirar o Wi-Fi da casa toda à noite', 'Que basta cobrir o aparelho com um pano grosso']::text[], 'O botão corta o microfone, e a luz vermelha confirma. Pelo app, ele controla as opções de privacidade e o histórico de voz.', 'Amazon Echo', true, now()),
  ('cas-24', 'casa-inteligente', 'instalacao', 'Lâmpada inteligente instalada num ponto com interruptor comum. Como orientar o cliente?', array['Deixar o interruptor sempre ligado', 'Desligar o interruptor toda noite para economizar energia', 'Desligar o interruptor de vez em quando para a lâmpada descansar', 'Tanto faz']::text[], 'Com o interruptor desligado, a lâmpada fica sem energia e sai da rede. Por isso as automações param.', 'Prática de campo', true, now()),
  ('cas-25', 'casa-inteligente', 'instalacao', 'Pode colocar lâmpada inteligente num circuito com dimmer comum?', array['Não, o dimmer atrapalha', 'Sim, fica ainda melhor para regular a luz', 'Sim, desde que o dimmer fique sempre no máximo', 'Sim, desde que a lâmpada seja de luz branca']::text[], 'A lâmpada inteligente já controla o próprio brilho. O dimmer comum corta a energia e faz ela piscar ou desconectar.', 'Prática de campo', true, now()),
  ('cas-26', 'casa-inteligente', 'instalacao', 'O que acontece com o interruptor inteligente touch se a internet cair?', array['As teclas continuam funcionando', 'A luz fica acesa até a internet voltar', 'O interruptor queima com a queda da conexão', 'Precisa trocar o interruptor ou configurar tudo de novo']::text[], 'O interruptor permite acionar manualmente pelas teclas. Sem internet, param o app e as automações.', 'Manual Intelbras', true, now()),
  ('cas-27', 'casa-inteligente', 'instalacao', 'Depois de configurar as rotinas, o que fazer com o cliente?', array['Testar com ele e ensinar o uso sem internet', 'Ir embora', 'Desligar as rotinas para não gastar energia à toa', 'Deixar o app instalado só no seu celular']::text[], 'O cliente precisa saber usar e saber o que fazer quando a rede falha.', 'Prática de campo', true, now()),
  ('cas-28', 'casa-inteligente', 'instalacao', 'Vai instalar uma fechadura inteligente. O que não pode faltar?', array['Um jeito de entrar sem pilha', 'Só o aplicativo no celular do cliente, que já basta', 'Uma senha igual à do Wi-Fi', 'Tirar o cilindro da chave']::text[], 'Sem pilha ou sem internet, o cliente precisa de outra forma de entrar.', 'Prática de campo', true, now()),
  ('cas-29', 'casa-inteligente', 'privacidade', 'O cliente quer uma câmera inteligente no quarto da babá, sem avisar. O que você diz?', array['Que isso invade a privacidade dela', 'Que pode, porque a casa é dele e ele decide', 'Que pode, desde que a câmera seja pequena e discreta', 'Que pode, desde que a câmera não grave áudio']::text[], 'Imagem de pessoas é dado pessoal. Filmar quarto ou banheiro de outra pessoa sem aviso fere a privacidade e pode dar processo.', 'Prática de campo', true, now()),
  ('cas-30', 'casa-inteligente', 'eletrica', 'Ao instalar um módulo inteligente atrás de um interruptor, o que conferir com o testador antes de encostar nos fios?', array['Que não há tensão nos fios', 'Só a cor dos fios', 'Se o sinal do Wi-Fi chega até a caixa', 'Nada, porque o disjuntor já foi desligado']::text[], 'O quadro pode estar com identificação errada. Desligar não basta: é preciso confirmar a ausência de tensão.', 'NR-10', true, now())
insert into public.quiz_tests (service_id, label, draw, pass, minutes) values ('chaveiro', 'Chaveiro', 15, 11, 15)
insert into private.quiz_questions (id, service_id, topic, question, options, why, source, active, updated_at) values
  ('cha-01', 'chaveiro', 'conduta', 'Uma pessoa chama para abrir a porta de uma casa porque perdeu a chave. O que fazer antes de abrir?', array['Confirmar que ela mora ali ou tem direito de entrar', 'Abrir logo, porque ela está com pressa e pode ser emergência', 'Abrir primeiro e pedir o documento quando ela entrar', 'Abrir se ela descrever bem como é a sala por dentro']::text[], 'Abrir para quem não tem direito pode tornar o chaveiro parte de um furto ou de uma invasão de domicílio.', 'Código Penal', true, now()),
  ('cha-02', 'chaveiro', 'conduta', 'A pessoa não consegue provar que mora no imóvel, insiste e oferece pagar o dobro. O que você faz?', array['Não abro e indico síndico, dono ou polícia', 'Abro, porque quem paga o dobro está falando a verdade', 'Abro só a fechadura de cima', 'Abro e tiro uma foto dela para me proteger']::text[], 'Pagar a mais não prova o direito de entrar. A responsabilidade de abrir para a pessoa errada é de quem abre.', 'Código Penal', true, now()),
  ('cha-03', 'chaveiro', 'conduta', 'Chamado para abrir um carro trancado. O que conferir?', array['Documento do carro e identidade', 'Se a pessoa tem a chave reserva em casa', 'Nada, carro não precisa de documento', 'Se o carro é novo ou usado']::text[], 'Abrir carro de outra pessoa sem confirmar o dono pode ajudar num furto.', 'Código Penal', true, now()),
  ('cha-04', 'chaveiro', 'conduta', 'Um vizinho pede para você abrir a porta porque a idosa da casa não responde. O que fazer?', array['Chamar bombeiros (193) ou polícia (190)', 'Abrir na hora', 'Esperar até o dia seguinte para ver se ela responde', 'Abrir, entrar com o vizinho e depois avisar a família']::text[], 'É uma emergência, e o vizinho não tem direito de entrar. Bombeiros e polícia podem agir e entrar legalmente.', 'Código Penal', true, now()),
  ('cha-05', 'chaveiro', 'conduta', 'Um cliente pede cópia de uma chave que não é dele, "de um amigo", a partir de uma foto. O que você faz?', array['Recuso: só para o dono ou com autorização', 'Copio, porque a foto mostra bem o segredo', 'Copio, mas cobro mais pelo risco', 'Copio e guardo uma cópia comigo, por garantia']::text[], 'Fazer chave para quem não tem direito pode servir a um furto qualificado pelo uso de chave falsa.', 'Código Penal', true, now()),
  ('cha-06', 'chaveiro', 'conduta', 'A chave tem gravado "não copiar" e é do sistema do condomínio. O morador quer uma cópia. O que fazer?', array['Pedir autorização do responsável', 'Copiar, porque a gravação não tem valor legal', 'Copiar e lixar a gravação para não chamar atenção', 'Copiar duas']::text[], 'Chaves controladas existem para o responsável saber quantas cópias há. Copiar sem autorização quebra esse controle.', 'Prática de campo', true, now()),
  ('cha-07', 'chaveiro', 'conduta', 'Depois de uma abertura de porta, o que é boa prática registrar?', array['Nome, documento, endereço, data e serviço', 'Nada, para não gerar prova contra o chaveiro', 'Só o valor cobrado e a forma de pagamento', 'A senha do alarme']::text[], 'O registro protege o chaveiro se houver problema depois. No DF, por exemplo, há cadastro e fiscalização dos prestadores.', 'Portaria SSPDS/DF', true, now()),
  ('cha-08', 'chaveiro', 'conduta', 'Durante a abertura da porta, quem deve estar no local?', array['Um adulto responsável', 'Ninguém, o chaveiro trabalha melhor sozinho', 'Uma criança da casa', 'Qualquer vizinho que esteja por perto']::text[], 'Serviços de chaveiro de seguradoras exigem um responsável maior de 18 anos presente. Isso protege o cliente e o profissional.', 'Porto Seguro', true, now()),
  ('cha-09', 'chaveiro', 'conduta', 'Antes de começar uma abertura que pode estragar a fechadura, o que o cliente precisa saber?', array['O preço e o risco de danificar', 'Nada, ele vê o valor na hora de pagar', 'Só o tempo que o serviço vai levar', 'Que o preço é combinado depois de abrir']::text[], 'O CDC obriga o orçamento prévio. Método destrutivo exige explicar e ter o ok do cliente.', 'Código de Defesa do Consumidor', true, now()),
  ('cha-10', 'chaveiro', 'conduta', 'Depois do serviço, o que fazer com o código ou o molde da chave do cliente?', array['Não guardar sem motivo nem expor o endereço', 'Guardar para oferecer cópias depois, sem ele pedir', 'Postar nas redes como exemplo de serviço bem feito', 'Anotar no caderno junto com o endereço']::text[], 'O código da chave junto com o endereço dá acesso à casa do cliente.', 'Prática de campo', true, now()),
  ('cha-11', 'chaveiro', 'tecnica', 'O cliente se mudou para uma casa e não sabe quem tem cópias. O que orientar?', array['Trocar o segredo das portas', 'Fazer mais cópias das chaves que vieram com a casa', 'Lubrificar as fechaduras para durarem mais', 'Nada, as chaves antigas se perdem com o tempo']::text[], 'Quem tinha a chave antiga continua abrindo. Trocar o cilindro muda o segredo.', 'Prática de campo', true, now()),
  ('cha-12', 'chaveiro', 'tecnica', 'Para trocar o segredo, é sempre preciso trocar a fechadura inteira?', array['Não, basta trocar o cilindro', 'Sim, sempre, porque o segredo fica na caixa', 'Sim, e também a contratesta do batente', 'Não, basta trocar a maçaneta']::text[], 'O segredo fica no cilindro. Trocar só ele sai mais barato e mantém a fechadura.', 'Prática de campo', true, now()),
  ('cha-13', 'chaveiro', 'tecnica', 'Uma fechadura tetra é instalada numa porta fina com batente frouxo. A porta fica segura?', array['Não muito: porta e batente também contam', 'Sim, a fechadura tetra resolve sozinha', 'Sim, se a chave for nova e original', 'Sim, desde que a porta tenha olho mágico']::text[], 'Fechadura boa em porta fraca ou batente mal fixado perde boa parte da vantagem.', 'Segurança da porta', true, now()),
  ('cha-14', 'chaveiro', 'tecnica', 'Qual norma trata dos requisitos e ensaios de fechaduras de embutir?', array['ABNT NBR 14913', 'NR-10, que trata de segurança das instalações', 'NBR 5410', 'NBR 8160, de sistemas prediais']::text[], 'A NBR 14913 fixa requisitos de segurança e ensaios, inclusive de tentativa de arrombamento. A NBR 16833 trata de seleção, instalação e manutenção.', 'NBR 14913', true, now()),
  ('cha-15', 'chaveiro', 'tecnica', 'Fechadura nova instalada, mas a lingueta não entra direito na contratesta. O que fazer?', array['Ajustar a contratesta até a lingueta entrar', 'Lixar a lingueta até ela caber no furo', 'Deixar assim, a porta fica encostada', 'Tirar a contratesta e trancar direto no batente']::text[], 'Lingueta que não entra toda deixa a porta sem trancar de verdade e força o mecanismo.', 'NBR 14913', true, now()),
  ('cha-16', 'chaveiro', 'tecnica', 'A chave começou a girar com dificuldade. O que verificar antes de trocar a fechadura?', array['Se a porta caiu e força a lingueta', 'Se a chave é de outra cor ou de outro fabricante', 'Se o cliente está girando para o lado certo', 'Nada, fechadura dura tem que ser trocada']::text[], 'Muitas vezes o problema é a porta arriada forçando o trinco, não a fechadura.', 'Prática de campo', true, now()),
  ('cha-17', 'chaveiro', 'tecnica', 'O fabricante Stam orienta como lubrificar suas fechaduras?', array['Uma gota de óleo mineral a cada 6 meses', 'Grafite em pó toda semana dentro do cilindro', 'Desengripante em spray dentro do cilindro', 'Graxa grossa no miolo e na lingueta']::text[], 'O manual diz que o grafite forma pasta com o óleo do mecanismo e desaconselha desengripante. Siga sempre o fabricante da fechadura.', 'Manual Stam', true, now()),
  ('cha-18', 'chaveiro', 'tecnica', 'Como limpar a fechadura sem estragar o acabamento?', array['Pano com sabão neutro ou álcool 70%', 'Água sanitária diluída', 'Palha de aço fina, que não risca o metal', 'Thinner, que tira mancha de tinta e gordura']::text[], 'Produtos com cloro e abrasivos atacam o acabamento.', 'Manual Stam', true, now()),
  ('cha-19', 'chaveiro', 'tecnica', 'A chave quebrou dentro do cilindro. Como tirar?', array['Com extrator de chave', 'Colocando cola na ponta e puxando quando secar', 'Empurrando com outra chave até sair do outro lado', 'Batendo na fechadura até o pedaço soltar']::text[], 'Forçar empurra o pedaço para dentro e trava os pinos. Cola pode estragar o cilindro de vez.', 'Prática de campo', true, now()),
  ('cha-20', 'chaveiro', 'automotivo', 'Você copiou a parte de metal de uma chave codificada. A cópia abre a porta, mas o carro não liga. Por quê?', array['Falta programar o transponder', 'A bateria do carro está fraca para dar partida', 'O corte ficou justo demais e não gira a ignição', 'Precisa lubrificar a ignição para a chave nova']::text[], 'O imobilizador só libera o motor quando reconhece o código do transponder. A cópia mecânica não leva o código.', 'Chave codificada', true, now()),
  ('cha-21', 'chaveiro', 'automotivo', 'O que é o transponder da chave do carro?', array['Um chip com código que libera a partida', 'A pilha que faz o controle da chave funcionar', 'O botão que abre o porta-malas a distância', 'A capa de borracha que protege a chave']::text[], 'Junto com a central, forma o sistema imobilizador: sem o código certo, o carro não liga.', 'Chave codificada', true, now()),
  ('cha-22', 'chaveiro', 'automotivo', 'Um cliente com carro de marca premium quer cópia codificada. O que avisar?', array['Que em algumas só a concessionária codifica', 'Que todo chaveiro codifica qualquer carro', 'Que carro premium não precisa codificar', 'Que basta copiar o metal da chave']::text[], 'Algumas montadoras fazem a chave só na matriz e codificam só na rede oficial.', 'Chave codificada', true, now()),
  ('cha-23', 'chaveiro', 'automotivo', 'A chave codificada parou de funcionar depois de cair no chão. Qual é a causa provável?', array['O transponder foi danificado', 'A chave ficou suja de poeira por dentro', 'O carro esqueceu a chave por causa do tombo', 'Falta óleo na ignição depois da queda']::text[], 'Pancada forte pode quebrar o chip. Também pode haver falha no receptor da ignição.', 'Chave codificada', true, now()),
  ('cha-24', 'chaveiro', 'automotivo', 'Para abrir um carro sem a chave, qual é o cuidado?', array['Ferramentas que não riscam nem rasgam', 'Arame forçando a janela pela borracha', 'Quebrar o vidro menor', 'Chave de fenda forçando a porta']::text[], 'O objetivo é abrir sem dano. Arame e alavanca improvisada estragam borracha, pintura e peças internas.', 'Prática de campo', true, now()),
  ('cha-25', 'chaveiro', 'tecnica', 'Abrir uma porta: por onde começar?', array['Métodos sem dano; destrutivo só com ok', 'Furando o cilindro, que é mais rápido e certo', 'Forçando o batente, que depois é só pintar', 'Tirando a porta das dobradiças sem avisar']::text[], 'Método destrutivo gera custo para o cliente e precisa ser combinado antes.', 'Código de Defesa do Consumidor', true, now()),
  ('cha-26', 'chaveiro', 'tecnica', 'O que é um sistema de chave mestra?', array['Uma chave que abre várias fechaduras', 'Uma chave que abre qualquer porta da cidade', 'A chave do carro que liga também o alarme', 'A chave reserva que fica com o síndico']::text[], 'É comum em prédios e empresas. Como a mestra abre tudo, as cópias precisam ser controladas.', 'Prática de campo', true, now()),
  ('cha-27', 'chaveiro', 'digital', 'A fechadura digital avisa pilha fraca. O que orientar?', array['Trocar as pilhas e saber a entrada de emergência', 'Esperar as pilhas acabarem de vez para trocar', 'Tirar as pilhas à noite para economizar', 'Desligar o aviso nas configurações']::text[], 'Sem pilha, só se entra pela chave mecânica ou pela alimentação de emergência. O cliente precisa saber disso antes.', 'Prática de campo', true, now()),
  ('cha-28', 'chaveiro', 'digital', 'Antes de instalar uma fechadura digital, o que conferir na porta?', array['Espessura, sentido de abertura e furação', 'Só a cor da porta e do acabamento', 'Se a porta tem olho mágico e trinco', 'Se a casa tem Wi-Fi rápido e estável']::text[], 'Cada modelo aceita uma faixa de espessura e um sentido de abertura. Errar obriga a refazer a furação.', 'Prática de campo', true, now()),
  ('cha-29', 'chaveiro', 'conduta', 'O síndico pede um cadeado na porta da escada de emergência. O que você diz?', array['Que a saída precisa abrir por dentro sem chave', 'Que pode, desde que seja um cadeado de qualidade', 'Que pode, desde que só tranque à noite', 'Que pode, se deixar a chave com o porteiro']::text[], 'Porta de rota de fuga deve destravar na hora, por dentro. Trancada, vira armadilha num incêndio.', 'Saída de emergência', true, now()),
  ('cha-30', 'chaveiro', 'conduta', 'O cliente quer cópia de uma chave de cofre de empresa e diz ser funcionário. O que fazer?', array['Pedir autorização da empresa', 'Copiar, porque ele tem a chave na mão', 'Copiar, mas cobrar mais por ser de cofre', 'Copiar e anotar o nome dele']::text[], 'Ter a chave na mão não significa ter direito de copiar. Num cofre, a autorização tem que vir do dono.', 'Código Penal', true, now())
insert into public.quiz_tests (service_id, label, draw, pass, minutes) values ('eletricista', 'Elétrica', 20, 14, 20)
insert into private.quiz_questions (id, service_id, topic, question, options, why, source, active, updated_at) values
  ('ele-01', 'eletricista', 'seguranca', 'Antes de trocar um chuveiro elétrico, o que você faz primeiro?', array['Desligo o disjuntor do chuveiro no quadro', 'Fecho o registro do banheiro para a água não molhar os fios', 'Coloco o seletor na posição desligado e espero esfriar', 'Uso luva de borracha e trabalho com cuidado, ligado']::text[], 'O seletor e o registro não cortam a energia dos fios. O manual pede desligar o disjuntor do circuito antes de começar a instalação elétrica.', 'Manual Lorenzetti', true, now()),
  ('ele-02', 'eletricista', 'seguranca', 'Você desligou o disjuntor que acha ser o do chuveiro. Antes de encostar nos fios, o que falta?', array['Testar com testador ou multímetro se não há tensão', 'Nada: com o disjuntor desligado, o circuito está seguro', 'Pedir ao cliente para apagar as luzes e tirar os aparelhos da tomada', 'Encostar de leve com as costas da mão para conferir']::text[], 'Desligar não é o mesmo que desenergizar: a NR-10 exige constatar a ausência de tensão antes de liberar o trabalho. O quadro pode estar com identificação errada.', 'NR-10', true, now()),
  ('ele-03', 'eletricista', 'seguranca', 'Como evitar que alguém religue o disjuntor enquanto você trabalha no circuito?', array['Travar o disjuntor e deixar um aviso no quadro', 'Fechar a tampa do quadro e pedir para ninguém mexer nele', 'Desligar também o interruptor do cômodo onde está trabalhando', 'Deixar o celular por perto para avisar se alguém religar']::text[], 'A NR-10 pede impedimento de reenergização e sinalização no ponto de desligamento.', 'NR-10', true, now()),
  ('ele-04', 'eletricista', 'seguranca', 'Antes de mexer em um quadro de energia, o que fazer com anel, relógio e corrente?', array['Tirar todos, porque metal conduz e pode enganchar', 'Pode manter', 'Tirar só o relógio', 'Cobrir anel e corrente com fita isolante antes de começar']::text[], 'A NR-10 proíbe adornos pessoais em serviços com eletricidade.', 'NR-10', true, now()),
  ('ele-05', 'eletricista', 'seguranca', 'Qual ferramenta é a certa para trabalhar em fiação elétrica?', array['Alicate e chave isolados para eletricista, em bom estado', 'Qualquer alicate, com várias voltas de fita isolante no cabo', 'Ferramenta comum, desde que a pessoa esteja de chinelo de borracha', 'Ferramenta de metal sem cabo, que dá mais firmeza no aperto']::text[], 'A NR-10 exige ferramentas e equipamentos adequados e isolados. Fita no cabo e chinelo não garantem isolamento.', 'NR-10', true, now()),
  ('ele-06', 'eletricista', 'seguranca', 'Para medir a tensão de uma tomada com multímetro, onde a chave deve estar?', array['Em tensão alternada (V~), faixa acima de 220 V', 'Em corrente (A)', 'Em resistência (Ω), para testar se o fio está inteiro', 'Em tensão contínua (V⎓), começando pela menor faixa']::text[], 'Tomada é tensão alternada. Medir em corrente ou resistência com a tomada ligada pode queimar o aparelho e causar curto.', 'Prática de campo', true, now()),
  ('ele-07', 'eletricista', 'seguranca', 'Que escada usar para trabalhar perto de fiação ou quadro energizado?', array['Escada de fibra de vidro ou madeira seca', 'Escada de alumínio, por ser mais leve e firme no piso', 'Qualquer escada', 'Escada de ferro']::text[], 'Escada metálica conduz eletricidade. Perto de partes energizadas, use material isolante.', 'NR-10', true, now()),
  ('ele-08', 'eletricista', 'chuveiro', 'Chuveiro novo instalado. Antes de ligar o disjuntor pela primeira vez, o que fazer?', array['Abrir o registro e deixar a água sair', 'Ligar o disjuntor e só depois abrir o registro devagar', 'Ligar no modo inverno por um minuto para testar a resistência', 'Esperar uma hora com o chuveiro seco antes de ligar']::text[], 'O fabricante pede fazer correr água antes de ligar a energia, para encher a câmara de aquecimento e não queimar a resistência.', 'Manual Lorenzetti', true, now()),
  ('ele-09', 'eletricista', 'chuveiro', 'O que fazer com o fio verde (ou verde e amarelo) do chuveiro?', array['Ligar ao fio terra da instalação', 'Ligar ao neutro, se não houver terra', 'Cortar, porque não é necessário', 'Enrolar e deixar solto dentro da caixa']::text[], 'O fio verde é o terra e deve ir a um sistema de aterramento. O manual proíbe usar o neutro como aterramento.', 'Manual Lorenzetti', true, now()),
  ('ele-10', 'eletricista', 'chuveiro', 'Como ligar os fios do chuveiro aos fios da parede?', array['Com conectores adequados à bitola', 'Com plugue e tomada, para facilitar a troca no futuro', 'Torcendo os fios bem firmes e cobrindo com fita crepe', 'Só torcendo os fios']::text[], 'O manual proíbe plugue ou tomada no chuveiro e pede conectores adequados.', 'Manual Lorenzetti', true, now()),
  ('ele-11', 'eletricista', 'chuveiro', 'De onde deve sair a alimentação do chuveiro?', array['De um circuito exclusivo, direto do quadro', 'Do mesmo circuito das tomadas do banheiro', 'Do circuito da iluminação, que já passa perto', 'De qualquer circuito com fio de 2,5 mm²']::text[], 'O manual pede linha direta e exclusiva do quadro. A NBR 5410 pede circuito próprio para aparelho acima de 10 A.', 'Manual Lorenzetti', true, now()),
  ('ele-12', 'eletricista', 'chuveiro', 'Chuveiro de 220 V ligado entre duas fases. Que disjuntor usar?', array['Bipolar', 'Unipolar em uma das fases, que já corta o circuito', 'Unipolar no neutro, junto com o DR do quadro', 'Nenhum: o DR já protege o chuveiro sozinho']::text[], 'Com duas fases, um disjuntor unipolar deixaria a outra fase energizada. O manual pede bipolar para 220 V fase-fase.', 'Manual Lorenzetti', true, now()),
  ('ele-13', 'eletricista', 'chuveiro', 'O que define a bitola do fio de um chuveiro?', array['Potência, tensão e distância até o quadro', 'Sempre 2,5 mm², que é o padrão de qualquer casa', 'Sempre 4 mm², que serve para qualquer chuveiro do mercado', 'Só a tensão: 127 V usa fio fino, e 220 V, fio grosso']::text[], 'A tabela do fabricante muda a seção do fio conforme o modelo, e para distâncias maiores pede fio mais grosso.', 'Manual Lorenzetti', true, now()),
  ('ele-14', 'eletricista', 'chuveiro', 'Um chuveiro de 7.500 W em 220 V puxa mais ou menos quanta corrente?', array['Cerca de 34 A', 'Cerca de 15 A', 'Cerca de 68 A', 'Cerca de 7,5 A']::text[], 'Corrente = potência ÷ tensão: 7.500 ÷ 220 ≈ 34 A. Por isso o fabricante indica disjuntor de 40 A e fio de 6 mm² para esse modelo.', 'Manual Lorenzetti', true, now()),
  ('ele-15', 'eletricista', 'chuveiro', 'Dois chuveiros com a mesma potência, um de 127 V e outro de 220 V. Qual precisa de fio mais grosso?', array['O de 127 V', 'O de 220 V, porque a tensão é maior', 'Os dois usam o mesmo fio, já que a potência é igual', 'Depende da marca e do tipo de resistência']::text[], 'Com a mesma potência, tensão menor significa corrente maior. No manual, o modelo 5.500 W/127 V pede 10 mm², e o 7.500 W/220 V pede 6 mm².', 'Manual Lorenzetti', true, now()),
  ('ele-16', 'eletricista', 'diagnostico', 'O DR desarma toda vez que o chuveiro liga. O que o fabricante indica verificar?', array['Aterramento ruim ou outro aparelho no circuito', 'O DR está sensível demais', 'A água está fria demais e a resistência força o circuito', 'Tirar o fio terra do chuveiro para o DR parar de cair']::text[], 'O manual aponta aterramento fora da NBR 5410 ou circuito compartilhado. Tirar o DR ou o terra remove a proteção contra choque.', 'Manual Lorenzetti', true, now()),
  ('ele-17', 'eletricista', 'diagnostico', 'A resistência de um chuveiro recém-instalado queimou no primeiro uso. Qual é a causa mais comum?', array['Ligaram a energia antes de a água encher o chuveiro', 'O registro foi aberto devagar e a pressão ficou baixa demais', 'O chuveiro foi ligado no modo verão na primeira vez', 'A caixa d’água estava cheia e a pressão ficou alta demais']::text[], 'Ligada sem água, a resistência aquece a seco e queima. O manual manda repetir a passagem de água sempre que o produto for retirado.', 'Manual Lorenzetti', true, now()),
  ('ele-18', 'eletricista', 'protecao', 'O disjuntor do chuveiro desarma sempre. O cliente pede para trocar por um maior. O que você faz?', array['Verifico a carga e o fio, pois o disjuntor depende do fio', 'Troco por um maior, que para de desarmar e resolve o problema', 'Coloco dois disjuntores iguais em paralelo para dividir a carga', 'Mantenho o disjuntor e prendo a alavanca para não cair']::text[], 'O disjuntor protege o fio. Um maior que o fio aguenta deixa o cabo esquentar sem desarmar, com risco de incêndio.', 'Cemig', true, now()),
  ('ele-19', 'eletricista', 'protecao', 'O disjuntor comum (termomagnético) serve principalmente para quê?', array['Proteger os fios contra sobrecarga e curto', 'Proteger as pessoas contra choque por fuga de corrente', 'Economizar energia desligando o que fica em stand-by', 'Estabilizar a tensão da casa quando a rua oscila']::text[], 'Proteção contra choque por fuga de corrente é função do DR. O disjuntor comum não detecta correntes pequenas que passam pelo corpo.', 'Procobre / NBR 5410', true, now()),
  ('ele-20', 'eletricista', 'protecao', 'O dispositivo DR serve para quê?', array['Desligar quando há fuga de corrente', 'Proteger a casa contra raios e picos de tensão da rua', 'Substituir o fio terra em casas que não têm aterramento', 'Aumentar a capacidade do circuito sem trocar o fio']::text[], 'O DR desliga correntes pequenas de fuga, que um disjuntor comum não percebe, mas que podem matar. Ele complementa o terra, não o substitui.', 'Procobre / NBR 5410', true, now()),
  ('ele-21', 'eletricista', 'protecao', 'Em quais circuitos a NBR 5410 exige DR de alta sensibilidade?', array['Banheiro, cozinha, lavanderia e tomadas externas', 'Só nos quartos, onde as pessoas dormem e ficam mais tempo', 'Só em comércio e indústria, não em casas', 'Só no quadro geral, protegendo a casa inteira de uma vez']::text[], 'A norma exige DR nos pontos de locais com chuveiro ou banheira, nas tomadas de áreas molhadas e nas externas.', 'Procobre / NBR 5410', true, now()),
  ('ele-22', 'eletricista', 'protecao', 'Você aperta o botão de teste (T) do DR e ele não desarma. O que isso indica?', array['O DR está com defeito e precisa ser trocado', 'Está normal: o botão só desarma com o circuito em uso', 'Falta apertar com mais força por um minuto', 'O circuito está sem carga, então é normal']::text[], 'O botão simula uma fuga. Se o DR não desarma no teste, ele não vai proteger num choque de verdade.', 'Procobre / NBR 5410', true, now()),
  ('ele-23', 'eletricista', 'protecao', 'Instalando um DR, como fica o neutro do circuito protegido?', array['Passa pelo DR e não é aterrado depois dele', 'Vai direto ao barramento de neutro', 'Passa pelo DR e depois é unido ao terra para garantir', 'Não precisa ser ligado']::text[], 'O DR compara a corrente da fase com a do neutro. Se o neutro for aterrado depois dele, o DR desarma ou deixa de proteger.', 'Procobre / NBR 5410', true, now()),
  ('ele-24', 'eletricista', 'protecao', 'Um interruptor DR (IDR) protege contra sobrecarga sozinho?', array['Não, precisa de disjuntor ou fusível junto', 'Sim, ele faz tudo o que o disjuntor faz e ainda protege contra choque', 'Sim, desde que seja tetrapolar', 'Não precisa: sobrecarga não é perigosa em casa']::text[], 'O interruptor DR só detecta fuga de corrente. Para sobrecarga e curto, é preciso um dispositivo de sobrecorrente antes dele.', 'Procobre / NBR 5410', true, now()),
  ('ele-25', 'eletricista', 'fios', 'Qual é a cor do fio neutro?', array['Azul-claro', 'Verde e amarelo', 'Preto', 'Vermelho']::text[], 'A NBR 5410 reserva o azul-claro para o neutro.', 'Procobre / NBR 5410', true, now()),
  ('ele-26', 'eletricista', 'fios', 'Qual é a cor do fio terra (proteção)?', array['Verde, ou verde e amarelo', 'Azul-claro', 'Branco', 'Qualquer cor, desde que marcada com fita']::text[], 'A NBR 5410 reserva o verde ou o verde-amarelo para o condutor de proteção.', 'Procobre / NBR 5410', true, now()),
  ('ele-27', 'eletricista', 'fios', 'Acabou o fio vermelho e sobrou fio verde e amarelo. Dá para usar como fase?', array['Não, essa cor é exclusiva do terra', 'Sim, se marcar a ponta com fita vermelha', 'Sim, em circuito de iluminação', 'Sim, se for só um trecho curto']::text[], 'A norma não admite exceção: verde-amarelo é só proteção. Quem mexer depois vai achar que é terra e levar choque.', 'NBR 5410', true, now()),
  ('ele-28', 'eletricista', 'fios', 'Qual é a seção mínima de fio para tomadas de uso geral numa casa?', array['2,5 mm²', '1,0 mm²', '1,5 mm²', '0,75 mm²']::text[], 'A NBR 5410 pede no mínimo 1,5 mm² para iluminação e 2,5 mm² para circuitos de força (tomadas).', 'Procobre / NBR 5410', true, now()),
  ('ele-29', 'eletricista', 'fios', 'Qual é a seção mínima de fio para circuitos de iluminação?', array['1,5 mm²', '0,5 mm²', '1,0 mm²', '4 mm²']::text[], 'A NBR 5410 pede no mínimo 1,5 mm² para iluminação.', 'Procobre / NBR 5410', true, now()),
  ('ele-30', 'eletricista', 'circuitos', 'Um aparelho que puxa mais de 10 A, como uma torneira elétrica, deve ficar em qual circuito?', array['Em um circuito só dele', 'No circuito das tomadas da cozinha', 'No circuito da iluminação', 'Em qualquer um']::text[], 'A NBR 5410 pede circuito independente para cada equipamento com corrente nominal acima de 10 A.', 'Procobre / NBR 5410', true, now()),
  ('ele-31', 'eletricista', 'circuitos', 'Iluminação e tomadas podem ficar no mesmo circuito numa instalação nova?', array['Não, a norma pede circuitos separados', 'Sim, sempre, desde que o disjuntor seja de 20 A', 'Sim, se o fio for de 1,5 mm² em todo o circuito', 'Só se as tomadas forem de 20 A e ficarem longe das luzes']::text[], 'A NBR 5410 pede circuitos de iluminação separados dos de tomadas de uso geral.', 'Procobre / NBR 5410', true, now()),
  ('ele-32', 'eletricista', 'iluminacao', 'Numa ligação de lâmpada com interruptor simples, qual fio o interruptor deve cortar?', array['A fase', 'O neutro', 'O terra', 'Tanto faz']::text[], 'Liga-se a fase ao interruptor e o neutro direto na lâmpada. Assim, com o interruptor desligado, a lâmpada fica sem tensão.', 'Procobre / NBR 5410', true, now()),
  ('ele-33', 'eletricista', 'diagnostico', 'O cliente levou choque ao trocar a lâmpada com o interruptor desligado. Qual é o erro provável?', array['O interruptor corta o neutro em vez da fase', 'A lâmpada era de LED, que guarda carga mesmo desligada', 'O interruptor é de tecla larga e não desliga totalmente', 'O disjuntor é grande demais e não desarmou no choque']::text[], 'Se o interruptor corta o neutro, o soquete continua com fase mesmo desligado. O certo é a fase passar pelo interruptor.', 'Procobre / NBR 5410', true, now()),
  ('ele-34', 'eletricista', 'iluminacao', 'No soquete de rosca, onde vai cada fio?', array['Retorno no contato central e neutro na rosca', 'Neutro no contato central e retorno na rosca', 'Terra no contato central e fase na rosca', 'Tanto faz, a lâmpada funciona dos dois jeitos']::text[], 'Com o neutro na rosca, quem encosta na parte de metal da lâmpada ao trocar não toca a fase.', 'Procobre / NBR 5410', true, now()),
  ('ele-35', 'eletricista', 'iluminacao', 'Ao instalar uma luminária com corpo de metal, o que não pode faltar?', array['Ligar o terra na carcaça', 'Ligar o neutro na carcaça metálica, que serve de terra', 'Isolar a carcaça por dentro com fita isolante', 'Nada: a lâmpada já é isolada e a carcaça não recebe energia']::text[], 'O terra na carcaça metálica faz a fuga de corrente ir para a terra e o DR desligar, em vez de passar pela pessoa.', 'Procobre / NBR 5410', true, now()),
  ('ele-36', 'eletricista', 'tomadas', 'Qual é a diferença entre a tomada de 10 A e a de 20 A no padrão brasileiro?', array['A de 20 A tem furo maior e aceita os dois plugues', 'Nenhuma, é só a cor e a marca que mudam', 'A de 10 A aceita os dois plugues', 'A de 20 A tem três furos, e a de 10 A, só dois']::text[], 'Plugue de 10 A tem pino de 4 mm e o de 20 A, de 4,8 mm. A tomada de 20 A aceita os dois. A de 10 A não aceita o de 20 A, de propósito.', 'NBR 14136', true, now()),
  ('ele-37', 'eletricista', 'tomadas', 'O plugue do micro-ondas (20 A) não entra na tomada de 10 A da cozinha. O que você faz?', array['Confiro se o circuito suporta e troco a tomada', 'Uso um adaptador de 20 A para 10 A, que é feito para isso', 'Lixo os pinos do plugue até entrarem na tomada de 10 A', 'Troco a tomada por uma de 20 A e o problema está resolvido']::text[], 'O pino grosso existe para o aparelho não ir para um circuito que não aguenta. A tomada só vira 20 A se o circuito for dimensionado para isso.', 'NBR 14136', true, now()),
  ('ele-38', 'eletricista', 'instalacao', 'Onde as emendas de fios devem ficar?', array['Em caixas acessíveis (de passagem ou de tomada)', 'Dentro do eletroduto, onde ficam protegidas da umidade', 'Embutidas no reboco, bem isoladas com fita', 'Em qualquer lugar, desde que a emenda esteja bem isolada']::text[], 'Emendas só em caixas acessíveis, nunca ao longo do eletroduto. Emenda escondida esquenta sem ninguém ver e não tem como ser revisada.', 'NBR 5410', true, now()),
  ('ele-39', 'eletricista', 'diagnostico', 'A tomada está escurecida e o plugue começou a derreter. Qual é a causa mais provável?', array['Mau contato ou sobrecarga na tomada', 'Tensão baixa na rua', 'Tomada branca', 'Excesso de aterramento na instalação da casa']::text[], 'Contato frouxo e sobrecarga geram calor no ponto da ligação. É preciso trocar a tomada, refazer o aperto e rever a carga do circuito.', 'Cemig', true, now()),
  ('ele-40', 'eletricista', 'diagnostico', 'Com aparelhos ligados no circuito, a caneta de teste acende nos dois furos da tomada. O que é mais provável?', array['Neutro interrompido antes da tomada', 'Tomada perfeita', 'Terra ligado certo', 'Caneta com bateria fraca']::text[], 'Com o neutro aberto, a fase volta pelos aparelhos ligados e aparece no furo do neutro. É preciso achar e refazer a conexão do neutro.', 'Prática de campo', true, now())
insert into public.quiz_tests (service_id, label, draw, pass, minutes) values ('encanador', 'Hidráulica', 20, 14, 20)
insert into private.quiz_questions (id, service_id, topic, question, options, why, source, active, updated_at) values
  ('enc-01', 'encanador', 'preparo', 'Antes de trocar a torneira da pia, o que você faz primeiro?', array['Fecho o registro da pia e abro a torneira', 'Desrosqueio devagar para a água sair aos poucos no balde', 'Fecho só a própria torneira, que já segura a água', 'Desligo o disjuntor geral e fecho a torneira da pia']::text[], 'Fechar a torneira não corta a água da rede. O registro de gaveta existe para bloquear o fluxo durante a manutenção, e abrir a torneira depois tira a pressão que ficou no cano.', 'Manual técnico Tigre', true, now()),
  ('enc-02', 'encanador', 'agua-fria', 'Qual é a sequência certa para soldar tubo e conexão de PVC de água fria?', array['Lixar, limpar, passar adesivo nas duas partes e encaixar', 'Passar adesivo só na ponta do tubo', 'Enrolar fita veda rosca na ponta e depois passar o adesivo', 'Aquecer a ponta do tubo para amolecer e encaixar sem adesivo']::text[], 'O fabricante pede lixar para tirar o brilho, limpar com solução preparadora para remover gordura e passar adesivo na bolsa e na ponta.', 'Manual técnico Tigre', true, now()),
  ('enc-03', 'encanador', 'agua-fria', 'Na hora de encaixar o tubo soldável na conexão, como se faz?', array['De uma vez, com ¼ de volta, e tiro o excesso', 'Aos poucos', 'Girando várias voltas para espalhar bem o adesivo por dentro', 'Batendo com martelo de borracha até a ponta chegar ao fundo']::text[], 'O manual da Tigre pede encaixe de uma vez, com ¼ de volta, até a posição final, e remover o excesso.', 'Manual técnico Tigre', true, now()),
  ('enc-04', 'encanador', 'agua-fria', 'Depois de soldar a tubulação de água fria, quanto esperar para fazer o teste de pressão?', array['12 horas', '5 minutos, porque o adesivo seca rápido', 'Não precisa esperar se a solda ficou bem feita', '1 hora, o mesmo tempo para encher de água']::text[], 'O fabricante pede 1 hora para encher a tubulação e 12 horas para o teste de pressão.', 'Manual técnico Tigre', true, now()),
  ('enc-05', 'encanador', 'agua-fria', 'Como aplicar a fita veda rosca?', array['No sentido da rosca, 3 a 4 voltas sobrepostas', 'No sentido contrário da rosca, para travar melhor no aperto', 'Umas 20 voltas, porque quanto mais fita, menos vaza', 'Uma volta só, para não engrossar a rosca']::text[], 'Contra a rosca, a fita desenrola ao apertar. Fita demais pode rachar a conexão. O fabricante indica 3 a 4 voltas em favor da rosca.', 'Manual técnico Tigre', true, now()),
  ('enc-06', 'encanador', 'agua-fria', 'Posso usar adesivo de PVC numa conexão roscável?', array['Não, rosca leva fita veda rosca', 'Sim, o adesivo veda melhor que a fita em rosca', 'Sim, passando a fita primeiro e o adesivo por cima', 'Só em rosca de água quente']::text[], 'O manual é direto: não usar adesivo de PVC nas roscas, porque para elas existe a fita veda rosca.', 'Manual técnico Tigre', true, now()),
  ('enc-07', 'encanador', 'agua-quente', 'O cliente quer levar água quente do aquecedor até a pia. Pode usar o tubo soldável marrom de água fria?', array['Não, uso tubo de água quente, como CPVC', 'Sim, se for o tubo de parede mais grossa da linha', 'Sim, se o trecho até a pia for curto e embutido', 'Sim, desde que envolva o tubo com isolante térmico']::text[], 'O PVC de água fria trabalha a até 20 °C e deforma com calor. O CPVC de água quente trabalha a 80 °C.', 'Manual técnico Tigre', true, now()),
  ('enc-08', 'encanador', 'agua-quente', 'Onde pode ficar um aquecedor de água a gás?', array['Em local com ventilação permanente', 'Dentro do box do banheiro', 'Em qualquer cômodo fechado', 'Dentro de um armário fechado']::text[], 'Aquecedor a gás em ambiente fechado acumula gases de queima. O manual pede ventilação permanente, com uma abertura acima de 1,5 m e outra abaixo de 0,80 m.', 'Manual técnico Tigre', true, now()),
  ('enc-09', 'encanador', 'agua-quente', 'A chama do aquecedor a gás está amarelada. O que isso indica?', array['Queimadores desregulados ou sujos', 'Está tudo normal, chama amarela esquenta mais', 'Falta água na caixa', 'O gás é de melhor qualidade']::text[], 'A chama certa é azulada. A amarela indica queima ruim, mais consumo e mais gás de combustão.', 'Manual técnico Tigre', true, now()),
  ('enc-10', 'encanador', 'testes', 'Quando testar se a tubulação nova tem vazamento?', array['Antes de fechar a parede, com a tubulação cheia', 'Depois do revestimento pronto', 'Não precisa testar se todas as soldas foram bem feitas', 'Só depois que o cliente reclamar de alguma mancha']::text[], 'O manual pede o teste antes de revestir, para achar falhas nas juntas sem quebrar nada depois.', 'Manual técnico Tigre', true, now()),
  ('enc-11', 'encanador', 'testes', 'No teste de estanqueidade da água fria, qual pressão usar?', array['1,5 vez a pressão estática, mínimo de 10 m.c.a.', 'A mesma pressão da rede, sem bomba, por alguns minutos', 'O dobro da pressão máxima que o tubo aguenta', 'Qualquer uma, o que importa é ver se pinga']::text[], 'A NBR 5626, citada no manual, pede 1,5 vez a pressão estática, nunca menos de 10 m.c.a., por 1 hora sem queda.', 'Manual técnico Tigre', true, now()),
  ('enc-12', 'encanador', 'esgoto', 'Qual é o caimento mínimo de um tubo de esgoto de 100 mm?', array['1%, ou seja, 1 cm para cada metro', 'Pode ser reto', '10%, quanto mais melhor', '0,1%, quase reto']::text[], 'A recomendação é 2% para diâmetros até 75 mm e 1% para 100 mm ou mais, com declividade constante.', 'Manual técnico Tigre', true, now()),
  ('enc-13', 'encanador', 'esgoto', 'Um ramal de esgoto de 40 mm vai ter 3 metros. Qual desnível mínimo entre o começo e o fim?', array['6 cm', '3 cm, porque o caimento mínimo é de 1%', 'Nenhum, se o tubo estiver bem colado', '30 cm, porque esgoto precisa de muita queda']::text[], 'Até 75 mm, o mínimo é 2%: 2 cm por metro. Em 3 metros, 6 cm.', 'Manual técnico Tigre', true, now()),
  ('enc-14', 'encanador', 'esgoto', 'Para que serve o sifão (ou a caixa sifonada)?', array['Manter água que barra o cheiro do esgoto', 'Aumentar a pressão da água que desce para o esgoto', 'Filtrar a água antes de ela ir para o esgoto', 'Segurar objetos que caem no ralo']::text[], 'A camada de água, chamada fecho hídrico, bloqueia os gases. A NBR 8160 pede no mínimo 5 cm de altura.', 'Manual técnico Tigre', true, now()),
  ('enc-15', 'encanador', 'diagnostico', 'Um banheiro que ficou meses sem uso está com cheiro de esgoto. O que é mais provável?', array['A água do sifão e do ralo secou', 'O cano de água fria está furado dentro da parede', 'A caixa d’água está suja e o cheiro vem pela torneira', 'O registro está meio fechado e a água ficou parada']::text[], 'Sem uso, o fecho hídrico evapora. Jogar água no ralo e no vaso refaz a barreira.', 'Manual técnico Tigre', true, now()),
  ('enc-16', 'encanador', 'esgoto', 'Para que serve a ventilação do esgoto (o tubo que sobe até o telhado)?', array['Proteger a água dos sifões e soltar os gases', 'Deixar o esgoto descer mais devagar nos trechos retos', 'Receber a água da chuva do telhado', 'Nada, ela só é exigida em prédio grande']::text[], 'Sem ventilação, a descarga puxa a água dos sifões e o cheiro entra. O tubo também leva os gases para a atmosfera.', 'Manual técnico Tigre', true, now()),
  ('enc-17', 'encanador', 'diagnostico', 'Toda vez que dão descarga, o ralo do banheiro borbulha e depois fica com cheiro. O que verificar?', array['Falta ou entupimento da ventilação', 'Pressão alta da rua entrando pelo esgoto', 'Registro do chuveiro com defeito, deixando água passar', 'Fita veda rosca mal passada no sifão da pia']::text[], 'A ventilação impede que a descarga quebre o fecho hídrico dos outros sifões. Borbulhar é sinal de que ela não está funcionando.', 'Manual técnico Tigre', true, now()),
  ('enc-18', 'encanador', 'esgoto', 'O cliente quer ligar a calha do telhado na rede de esgoto. O que você diz?', array['Não pode: chuva e esgoto são separados', 'Pode, a água da chuva ajuda a lavar o esgoto', 'Pode, desde que use tubo de 100 mm na ligação', 'Pode, desde que passe antes por uma caixa de gordura']::text[], 'A NBR 10844 proíbe ligar as águas pluviais no esgoto sanitário. Em chuva forte, o esgoto volta e traz mau cheiro.', 'Manual técnico Tigre', true, now()),
  ('enc-19', 'encanador', 'esgoto', 'No tubo de esgoto com anel de borracha, o que usar para encaixar?', array['Pasta lubrificante própria', 'Óleo de cozinha', 'Graxa ou vaselina, que duram mais', 'Adesivo de PVC']::text[], 'Óleo, vaselina e graxa atacam a borracha. O fabricante pede pasta lubrificante própria.', 'Manual técnico Tigre', true, now()),
  ('enc-20', 'encanador', 'esgoto', 'O que ajuda o tubo a entrar na bolsa com anel de borracha sem estragar o anel?', array['Chanfrar a ponta do tubo', 'Esquentar a bolsa com maçarico para alargar', 'Cortar um pedaço do anel para ficar mais fino', 'Passar adesivo de PVC no anel para deslizar']::text[], 'O chanfro na ponta deixa o tubo deslizar sem dobrar ou cortar o anel.', 'Manual técnico Tigre', true, now()),
  ('enc-21', 'encanador', 'esgoto', 'Para que serve a caixa de gordura?', array['Segurar a gordura da cozinha', 'Receber o esgoto do vaso sanitário antes da rua', 'Guardar a água da chuva para reaproveitar', 'Aumentar a pressão da água da pia da cozinha']::text[], 'Ela recebe o esgoto da cozinha e retém a gordura, por isso precisa de limpeza periódica.', 'Manual técnico Tigre', true, now()),
  ('enc-22', 'encanador', 'diagnostico', 'A pia da cozinha entope de novo poucas semanas depois de cada desentupimento. O que verificar?', array['Se a caixa de gordura está cheia', 'Se a torneira da pia está pingando o dia todo', 'Se a caixa d’água está tampada e sem ventilação', 'Se o registro geral está totalmente aberto']::text[], 'Com a caixa de gordura cheia, a gordura passa e endurece no cano. Desentupir só a pia não resolve.', 'Manual técnico Tigre', true, now()),
  ('enc-23', 'encanador', 'diagnostico', 'Como ver se a válvula ou a caixa de descarga está vazando para dentro do vaso?', array['Jogo pó de café no vaso e vejo se fica parado', 'Dou várias descargas seguidas e escuto o barulho', 'Olho se o chão em volta do vaso está molhado', 'Fecho o registro e vejo se o vaso esvazia sozinho']::text[], 'Se a água está entrando aos poucos, o pó se mexe ou some. Se fica parado no fundo, não há vazamento.', 'Manual técnico Tigre', true, now()),
  ('enc-24', 'encanador', 'diagnostico', 'A conta de água subiu e ninguém vê vazamento. Qual é o primeiro teste?', array['Fechar tudo e ver se o hidrômetro gira', 'Quebrar a parede do banheiro', 'Trocar todos os registros e torneiras da casa', 'Esperar a próxima conta para comparar o consumo']::text[], 'Se o hidrômetro gira sem ninguém usar água, há vazamento depois dele. O teste não mostra onde, mas confirma antes de quebrar.', 'SAAE', true, now()),
  ('enc-25', 'encanador', 'diagnostico', 'Casa abastecida por caixa d’água. Como descobrir se há vazamento na tubulação da casa?', array['Amarro a boia, marco o nível e confiro em 1 hora', 'Esvazio a caixa toda e vejo se ela enche de novo', 'Abro todas as torneiras ao mesmo tempo e olho a pressão', 'Olho se a boia está boa e se o ladrão está pingando']::text[], 'Com a boia vedada e ninguém usando água, o nível não pode baixar. Se baixar, há vazamento nos canos, nos sanitários ou na caixa.', 'Manual técnico Tigre', true, now()),
  ('enc-26', 'encanador', 'agua-fria', 'Qual é a diferença entre registro de gaveta e registro de pressão?', array['Gaveta bloqueia o trecho; pressão regula a vazão', 'São iguais, só muda o acabamento e o preço', 'O de gaveta aumenta a pressão, e o de pressão diminui', 'O de pressão só serve para água quente']::text[], 'O de gaveta é o registro geral do ambiente, para bloquear o fluxo em manutenções. O de pressão fica no ponto de uso, como chuveiro e bebedouro.', 'Manual técnico Tigre', true, now()),
  ('enc-27', 'encanador', 'agua-fria', 'Numa casa abastecida por caixa d’água, o que dá pressão à água no chuveiro?', array['A altura da caixa até o chuveiro', 'O diâmetro do registro do chuveiro', 'A potência do chuveiro instalado', 'A quantidade de água que chega da rua']::text[], 'Por gravidade, cada metro de altura dá cerca de 1 m.c.a. (10 kPa). Caixa logo acima do chuveiro dá pouca pressão.', 'Manual técnico Tigre', true, now()),
  ('enc-28', 'encanador', 'diagnostico', 'Depois de um conserto, a água sai aos trancos e com ar pela torneira. O que fazer?', array['Abrir as torneiras do ramal até sair o ar', 'Trocar o registro, que ficou com defeito', 'Fechar a caixa d’água por um dia inteiro', 'Apertar mais a fita veda rosca das conexões']::text[], 'Ar preso na tubulação sai abrindo os pontos de uso daquele circuito. É a solução indicada pelo fabricante.', 'Manual Lorenzetti', true, now()),
  ('enc-29', 'encanador', 'agua-fria', 'O que causa o golpe de aríete, aquela pancada forte no cano?', array['Fechamento rápido da água', 'Água quente demais passando pelo cano', 'Excesso de fita veda rosca nas conexões', 'Caixa d’água cheia demais, com a boia alta']::text[], 'A água em velocidade parando de repente gera picos de pressão. A solução é fechamento lento, válvula antigolpe ou caixa de descarga.', 'Manual técnico Tigre', true, now()),
  ('enc-30', 'encanador', 'agua-fria', 'A tubulação embutida pode ficar presa dentro de viga ou pilar de concreto?', array['Não, ela fica livre da estrutura e acessível', 'Sim, fica mais protegida dentro do concreto', 'Sim, desde que o tubo seja de parede grossa', 'Só a tubulação de esgoto pode ficar presa']::text[], 'O manual pede tubulação livre da estrutura, para não sofrer com a movimentação dela e permitir reparo.', 'Manual técnico Tigre', true, now()),
  ('enc-31', 'encanador', 'agua-fria', 'Tubo de PVC que vai ficar exposto ao sol no telhado. O que fazer?', array['Proteger do sol', 'Nada, o PVC não sofre com o sol', 'Usar tubo mais fino, que esquenta menos', 'Pintar com tinta preta, que protege do calor']::text[], 'A radiação do sol ataca o plástico de fora para dentro. A recomendação é proteger o tubo desde o transporte.', 'Manual técnico Tigre', true, now()),
  ('enc-32', 'encanador', 'agua-fria', 'Para que serve a válvula de retenção na saída da bomba?', array['Impedir o retorno da água', 'Aumentar a pressão de saída da bomba', 'Filtrar a água antes de chegar à caixa', 'Regular a temperatura da água bombeada']::text[], 'Ela só deixa a água passar num sentido e evita o retorno.', 'Manual técnico Tigre', true, now()),
  ('enc-33', 'encanador', 'agua-fria', 'Como ligar a bomba à tubulação para a vibração não rachar os canos?', array['Com um mangote de borracha', 'Com cano rígido bem preso na parede', 'Com cano de ferro, que é mais resistente', 'Com mais adesivo nas conexões perto da bomba']::text[], 'O mangote absorve a vibração da bomba.', 'Manual técnico Tigre', true, now()),
  ('enc-34', 'encanador', 'caixa', 'De quanto em quanto tempo a caixa d’água deve ser limpa?', array['No mínimo a cada 6 meses', 'A cada 5 anos', 'Só quando a água ficar com cor', 'Nunca, se estiver tampada']::text[], 'A orientação da Sabesp é limpeza e desinfecção no mínimo semestral.', 'Sabesp', true, now()),
  ('enc-35', 'encanador', 'caixa', 'Antes de começar a limpar a caixa d’água, o que fazer?', array['Fechar a entrada de água da caixa', 'Jogar água sanitária com a caixa ainda cheia', 'Esvaziar a caixa abrindo só o ladrão', 'Desligar o disjuntor do chuveiro elétrico']::text[], 'Sem fechar a entrada, a caixa continua enchendo durante a limpeza.', 'Manual técnico Tigre', true, now()),
  ('enc-36', 'encanador', 'caixa', 'Para esfregar a caixa d’água, o que pode usar?', array['Escova de fibra ou pano, sem sabão', 'Escova de aço com um pouco de sabão em pó', 'Detergente e desinfetante perfumado', 'Vassoura de piso e removedor de manchas']::text[], 'Sabão, detergente e outros produtos deixam resíduo na água de beber. Escova de aço danifica a caixa. A desinfecção é feita com água sanitária.', 'Secretaria da Saúde', true, now()),
  ('enc-37', 'encanador', 'caixa', 'Depois de colocar a água sanitária para desinfetar a caixa, o que fazer com essa água?', array['Esperar 2 horas e esvaziar pelas torneiras', 'Liberar para beber logo depois de misturar', 'Deixar uma semana na caixa para fazer efeito', 'Misturar com mais água e usar para cozinhar']::text[], 'Depois das 2 horas, a água sai abrindo torneiras e descargas. Assim a solução também desinfeta os canos da casa.', 'Manual técnico Tigre', true, now()),
  ('enc-38', 'encanador', 'agua-fria', 'Como ligar uma torneira de metal num tubo de PVC soldável?', array['Com conexão de transição com bucha de latão', 'Colando a rosca da torneira direto no tubo com adesivo', 'Esquentando o tubo para abrir a rosca nele', 'Com fita isolante bem apertada na emenda']::text[], 'A bucha de latão protege a rosca de PVC do desgaste do metal. Adesivo não vai em rosca.', 'Manual técnico Tigre', true, now()),
  ('enc-39', 'encanador', 'esgoto', 'Instalando um ralo linear no box, o que não pode faltar?', array['Ligar a uma caixa sifonada', 'Ligar direto no tubo de esgoto do banheiro', 'Deixar sem caimento', 'Ligar na tubulação da água da chuva']::text[], 'O ralo linear não tem sifão próprio. O fabricante exige caixa sifonada para impedir o retorno do mau cheiro.', 'Manual técnico Tigre', true, now()),
  ('enc-40', 'encanador', 'testes', 'No teste de pressão, a tubulação pode ser considerada sem vazamento quando:', array['Pressão estável por 1 hora', 'Não pinga nos primeiros 5 minutos de teste', 'O manômetro sobe quando a bomba é ligada', 'O cliente olha as conexões e aprova']::text[], 'O manual, seguindo a NBR 5626, pede 1 hora na pressão de ensaio sem queda. Se cair, conserta e repete.', 'Manual técnico Tigre', true, now())
insert into public.quiz_tests (service_id, label, draw, pass, minutes) values ('informatica', 'Informática', 15, 11, 15)
insert into private.quiz_questions (id, service_id, topic, question, options, why, source, active, updated_at) values
  ('inf-01', 'informatica', 'dados', 'O cliente pede para formatar o notebook. O que fazer antes?', array['Combinar o que salvar e fazer backup', 'Formatar direto, porque ele já sabe que perde tudo', 'Copiar só a área de trabalho, que é onde ficam os arquivos', 'Formatar e tentar recuperar os arquivos depois, se ele pedir']::text[], 'Manutenção e reinstalação são situações de risco: o CERT.br recomenda backup antes delas. E é o cliente quem diz o que é importante.', 'CERT.br', true, now()),
  ('inf-02', 'informatica', 'dados', 'Qual é a orientação certa sobre cópias de segurança?', array['Pelo menos 2 cópias, em lugares diferentes', 'Uma cópia numa pasta separada do mesmo HD basta', 'Uma cópia só', 'Backup só é necessário em computador de empresa']::text[], '"Quem tem 1 não tem nenhum": se uma cópia falhar, existe a outra. O CERT.br pede ao menos 2, em locais diferentes.', 'CERT.br', true, now()),
  ('inf-03', 'informatica', 'dados', 'Por que configurar backup automático para o cliente?', array['Esquece menos e mantém as cópias em dia', 'Porque deixa o computador mais rápido no dia a dia', 'Porque com ele o antivírus deixa de ser necessário', 'Porque apaga os arquivos antigos do PC para liberar espaço']::text[], 'Backup automático é menos propenso a esquecimento. Se for em disco externo, ele precisa estar conectado para rodar.', 'CERT.br', true, now()),
  ('inf-04', 'informatica', 'seguranca', 'Configurando backup em nuvem para o cliente, o que mais ativar?', array['Verificação em duas etapas', 'Uma senha curta', 'Compartilhamento público da pasta, para facilitar', 'Nada, porque a nuvem já é segura por padrão']::text[], 'Contas de nuvem são visadas por atacantes. O CERT.br diz que só a senha não basta.', 'CERT.br', true, now()),
  ('inf-05', 'informatica', 'dados', 'Durante o conserto, você tem acesso às fotos e documentos do cliente. Como agir?', array['Mexer só no necessário para o serviço', 'Abrir as fotos para conferir se não se corromperam', 'Copiar tudo para o seu computador, por garantia', 'Mostrar ao colega algum arquivo que chamou atenção']::text[], 'Pela LGPD, o uso dos dados fica limitado à finalidade, que aqui é o conserto. Abrir ou copiar além disso é uso indevido.', 'LGPD', true, now()),
  ('inf-06', 'informatica', 'dados', 'Você fez uma cópia temporária dos arquivos do cliente para formatar. Depois de devolver tudo:', array['Apago a cópia que ficou comigo', 'Guardo para sempre, caso ele precise', 'Uso como exemplo para outros clientes', 'Vendo o HD com os arquivos']::text[], 'Terminado o serviço, os dados devem ser eliminados. Guardar arquivos do cliente sem motivo é risco para ele e para você.', 'LGPD', true, now()),
  ('inf-07', 'informatica', 'hardware', 'Antes de abrir um notebook para trocar a memória, o que fazer?', array['Desligar, tirar o carregador e a bateria se o manual pedir', 'Só fechar a tampa, que o notebook entra em repouso', 'Deixar ligado para ver se a memória nova é reconhecida', 'Colocar em modo de suspensão e tirar o carregador']::text[], 'Os manuais de serviço pedem tirar a energia, e em vários modelos remover a bateria, para não danificar a placa-mãe.', 'Manual Dell', true, now()),
  ('inf-08', 'informatica', 'hardware', 'Como evitar estragar componentes com eletricidade estática ao mexer dentro do computador?', array['Pulseira antiestática ou tocar em metal sem pintura', 'Trabalhar sobre um tapete de lã, que isola a mesa', 'Usar luvas de lã', 'Esfregar as mãos antes para descarregar a eletricidade']::text[], 'A descarga eletrostática queima componentes sem você perceber. Os manuais pedem pulseira ou contato com metal sem pintura.', 'Manual Dell', true, now()),
  ('inf-09', 'informatica', 'hardware', 'Como segurar um pente de memória ou uma placa?', array['Pelas bordas, sem tocar nos contatos', 'Pelos contatos dourados, que são a parte mais firme', 'Pelos chips do meio, que não quebram', 'Tanto faz, desde que o PC esteja desligado']::text[], 'Gordura e estática nos contatos causam mau contato e danos. O manual pede segurar pelas bordas.', 'Manual Dell', true, now()),
  ('inf-10', 'informatica', 'hardware', 'O computador do cliente ainda está na garantia do fabricante. O que avisar antes de abrir?', array['Que pode perder a garantia', 'Nada, a garantia continua valendo de qualquer jeito', 'Que a garantia fica maior depois da manutenção', 'Que a garantia só cobre o teclado e a tela']::text[], 'Os fabricantes avisam que danos de serviço não autorizado não são cobertos. O cliente precisa decidir sabendo disso.', 'Manual Dell', true, now()),
  ('inf-11', 'informatica', 'dados', 'O cliente apagou fotos sem querer. Qual é a primeira orientação?', array['Parar de usar e não instalar nada nesse disco', 'Instalar logo um programa de recuperação no mesmo disco', 'Desfragmentar o disco para juntar os pedaços dos arquivos', 'Reiniciar o computador para a lixeira voltar']::text[], 'O espaço apagado continua com os dados até ser sobrescrito. Instalar ou salvar arquivos ali reduz a chance de recuperar.', 'Recuperação de arquivos', true, now()),
  ('inf-12', 'informatica', 'dados', 'Onde salvar os arquivos que você conseguiu recuperar?', array['Em outro disco ou pen drive', 'No mesmo disco de onde foram apagados', 'Na lixeira', 'Na área de trabalho do mesmo disco']::text[], 'Salvar na mesma unidade pode sobrescrever o que ainda não foi recuperado.', 'Recuperação de arquivos', true, now()),
  ('inf-13', 'informatica', 'legal', 'O cliente pede para instalar um programa pago "crackeado". O que você faz?', array['Recuso e ofereço uma opção legal', 'Instalo, porque todo mundo faz e ninguém fiscaliza', 'Instalo, mas sem contar para ele de onde veio', 'Instalo se ele assinar que a responsabilidade é dele']::text[], 'Usar programa sem licença viola a Lei do Software, e a Justiça já condenou usuários. Programa crackeado também costuma vir com vírus.', 'Lei do Software', true, now()),
  ('inf-14', 'informatica', 'sistema', 'O computador não aceita atualizar para o Windows 11. Qual exigência costuma faltar?', array['TPM 2.0 e UEFI com Inicialização Segura', 'Placa de som dedicada e drivers de áudio novos', 'Monitor de 4K e placa de vídeo dedicada', 'Teclado e mouse sem fio compatíveis']::text[], 'Os requisitos incluem TPM 2.0 e UEFI com Inicialização Segura, além de 4 GB de RAM e 64 GB de armazenamento.', 'Microsoft', true, now()),
  ('inf-15', 'informatica', 'rede', 'Instalando um roteador novo, qual é a primeira configuração de segurança?', array['Trocar a senha de administração padrão do roteador', 'Deixar a senha que veio de fábrica, para o cliente lembrar', 'Desligar a senha do Wi-Fi', 'Colocar o nome do cliente na rede']::text[], 'Senha padrão de fábrica pode ser descoberta por atacantes. Trocá-la dificulta invasão e alteração das configurações.', 'CERT.br', true, now()),
  ('inf-16', 'informatica', 'rede', 'Qual segurança escolher para o Wi-Fi?', array['WPA3 ou WPA2/WPA3', 'WEP, que é mais compatível', 'WPA', 'Rede aberta com senha só no roteador']::text[], 'O CERT.br pede a versão mais atual (WPA3 ou WPA2/WPA3) e diz para não usar WEP nem WPA.', 'CERT.br', true, now()),
  ('inf-17', 'informatica', 'rede', 'Que nome dar à rede Wi-Fi do cliente?', array['Um nome único, sem dados pessoais', 'O nome dele e o número do apartamento, para achar fácil', 'O nome que veio de fábrica, impresso no roteador', 'O nome do provedor junto com o modelo do aparelho']::text[], 'Nome com apartamento ajuda criminosos, e nome de fábrica revela o modelo e as falhas conhecidas dele.', 'CERT.br', true, now()),
  ('inf-18', 'informatica', 'rede', 'O que fazer quanto às atualizações do roteador?', array['Ativar a atualização automática', 'Desativar', 'Atualizar só quando o roteador parar de funcionar', 'Nada, roteador não recebe atualização']::text[], 'Roteadores também têm falhas de segurança corrigidas por atualização.', 'CERT.br', true, now()),
  ('inf-19', 'informatica', 'seguranca', 'Ajudando o cliente a criar uma senha, o que evitar?', array['Datas, nomes e sequências como 123456', 'Senha longa, com mais de 12 caracteres', 'Juntar várias palavras numa frase', 'Usar um gerenciador de senhas']::text[], 'Informações pessoais e sequências de teclado são as primeiras que os atacantes tentam.', 'CERT.br', true, now()),
  ('inf-20', 'informatica', 'rede', 'O celular de alguém da casa foi furtado. O que fazer com o Wi-Fi?', array['Trocar a senha do Wi-Fi', 'Nada', 'Desligar o roteador por um dia', 'Mudar só o nome da rede']::text[], 'O aparelho furtado já sabe a senha. O CERT.br manda trocar nesse caso.', 'CERT.br', true, now()),
  ('inf-21', 'informatica', 'seguranca', 'O cliente recebeu um e-mail do "banco" pedindo para clicar e atualizar os dados. O que orientar?', array['Não clicar e entrar pelo app ou site oficial', 'Clicar, se o logotipo e as cores forem iguais aos do banco', 'Responder o e-mail pedindo para confirmarem a origem', 'Encaminhar para os amigos conferirem se receberam também']::text[], 'É o golpe mais comum (phishing). O acesso deve ser sempre pelo canal oficial, nunca pelo link recebido.', 'CERT.br', true, now()),
  ('inf-22', 'informatica', 'diagnostico', 'Notebook muito lento. Antes de formatar, o que verificar?', array['Disco cheio, programas na inicialização e o HD', 'Só a resolução da tela e o papel de parede', 'Nada, formatar resolve qualquer lentidão', 'O tamanho da tela e o brilho']::text[], 'Disco cheio, excesso de programas na inicialização e HD falhando deixam o computador lento, e formatar não resolve HD com defeito.', 'Prática de campo', true, now()),
  ('inf-23', 'informatica', 'hardware', 'Notebook antigo com HD, bem lento. Qual troca costuma dar o maior ganho de velocidade?', array['Trocar o HD por SSD', 'Trocar o teclado por um mecânico', 'Trocar a bateria por uma nova', 'Trocar a tela por uma de alta resolução']::text[], 'O SSD é muitas vezes mais rápido que o HD na leitura. Em máquina antiga é o upgrade que mais se sente.', 'Prática de campo', true, now()),
  ('inf-24', 'informatica', 'diagnostico', 'O computador desliga sozinho quando esquenta. O que verificar?', array['Poeira, cooler e pasta térmica', 'O antivírus', 'O monitor', 'A versão do navegador e as extensões instaladas']::text[], 'Superaquecimento faz o sistema desligar para se proteger. Limpeza e pasta térmica nova costumam resolver.', 'Prática de campo', true, now()),
  ('inf-25', 'informatica', 'dados', 'Você precisa da senha do computador do cliente para o serviço. Como fazer?', array['Ele digita ou troca depois; não anoto', 'Anotar num papel colado no notebook até terminar', 'Pedir também a senha do banco, para testar o acesso', 'Guardar no meu celular para a próxima manutenção']::text[], 'A senha é do cliente. O correto é usar só durante o serviço e orientá-lo a trocar depois.', 'Prática de campo', true, now()),
  ('inf-26', 'informatica', 'seguranca', 'O cliente quer dois antivírus ao mesmo tempo, "para proteger mais". O que dizer?', array['Um ativo basta; dois conflitam', 'Que é ótimo, quanto mais antivírus melhor', 'Que precisa de três', 'Que antivírus não serve para nada hoje em dia']::text[], 'Dois antivírus em tempo real disputam os mesmos arquivos e podem travar o sistema.', 'Prática de campo', true, now()),
  ('inf-27', 'informatica', 'sistema', 'De onde baixar o driver da placa de vídeo ou da impressora?', array['Do site do fabricante', 'Do primeiro site que aparecer na busca', 'De um pen drive de outro cliente', 'De um anúncio de "driver grátis"']::text[], 'Sites de terceiros costumam trazer versões erradas ou com vírus.', 'Prática de campo', true, now()),
  ('inf-28', 'informatica', 'hardware', 'O carregador do notebook quebrou. O que usar no lugar?', array['Original ou com mesma tensão, potência e conector', 'Qualquer um que encaixe no conector do notebook', 'Um de potência bem menor, que esquenta menos', 'Um carregador de celular com adaptador de ponta']::text[], 'Tensão errada queima a placa, e potência baixa faz o carregador esquentar e não carregar.', 'Prática de campo', true, now()),
  ('inf-29', 'informatica', 'dados', 'Você vai fazer suporte remoto no computador do cliente. Como agir?', array['Com autorização, ele vendo, e encerrar no fim', 'Deixar o acesso remoto sempre ligado, para facilitar o suporte', 'Entrar quando for preciso, sem avisar, para não incomodar', 'Pedir para ele sair de perto durante o atendimento']::text[], 'Acesso remoto dá controle total do computador. Deve ser autorizado, acompanhado e encerrado ao final.', 'LGPD', true, now()),
  ('inf-30', 'informatica', 'dados', 'Para se proteger de vírus que sequestram arquivos (ransomware), como manter o backup?', array['Uma cópia desconectada do computador', 'Com o disco externo sempre ligado no PC, para copiar sempre', 'Só numa pasta oculta do mesmo HD', 'Não precisa de backup se tiver um bom antivírus']::text[], 'O ransomware criptografa tudo que estiver acessível, inclusive disco ligado. Uma cópia desligada ou em outro local escapa.', 'CERT.br', true, now()),
  ('inf-31', 'informatica', 'impressora', 'O cliente trocou a senha do Wi-Fi e a impressora parou de imprimir pela rede. O que fazer?', array['Reconfigurar o Wi-Fi da impressora', 'Reinstalar o Windows do computador do cliente', 'Trocar o cartucho', 'Desligar e ligar o roteador']::text[], 'A impressora guardou a senha antiga. É preciso colocá-la de novo no modo de configuração Wi-Fi e conectar à rede com a senha nova.', 'HP', true, now()),
  ('inf-32', 'informatica', 'impressora', 'A impressora some da rede de vez em quando e volta com outro endereço. Qual solução evita isso?', array['Reservar um IP para ela no roteador', 'Trocar a impressora por um modelo com cabo USB', 'Reinstalar o driver toda semana', 'Desligar o DHCP do roteador para a casa toda']::text[], 'Sem reserva, o roteador pode dar outro endereço à impressora, e o computador procura no endereço velho. A reserva no DHCP fixa o endereço.', 'Rede doméstica', true, now()),
  ('inf-33', 'informatica', 'impressora', 'O roteador usa endereços 192.168.15.x. Que IP reservar para a impressora?', array['Um 192.168.15.x livre', '192.168.0.50, que é o mais comum', 'Qualquer número, o roteador ajusta', 'O mesmo IP do roteador, para ficar fácil']::text[], 'Fora da faixa do roteador, a impressora fica invisível para os computadores. E o IP não pode repetir o de outro aparelho.', 'Rede doméstica', true, now()),
  ('inf-34', 'informatica', 'impressora', 'Durante a configuração sem fio da impressora, onde deixá-la?', array['Perto do roteador', 'No cômodo mais longe, onde ela vai ficar', 'Dentro de um armário, para testar o alcance', 'Tanto faz']::text[], 'O fabricante recomenda impressora e celular ou computador perto do roteador durante a instalação. Depois de configurada, ela vai para o lugar definitivo.', 'HP', true, now()),
  ('inf-35', 'informatica', 'tv', 'Como atualizar o software de uma smart TV Samsung?', array['Pelo menu, ou por pen drive sem desligar', 'Desligando da tomada até ela atualizar sozinha', 'Instalando um aplicativo de atualização de outra loja', 'Não se atualiza o sistema da TV']::text[], 'A Samsung indica atualizar pelo menu de configurações ou por USB quando a conexão é ruim. Desligar a TV ou tirar o pen drive no meio pode estragar o sistema.', 'Samsung', true, now()),
  ('inf-36', 'informatica', 'tv', 'A smart TV trava ao passar filmes em 4K. O que verificar primeiro?', array['A internet no local da TV', 'A marca e as pilhas do controle remoto', 'O brilho e o modo de imagem da tela', 'Se a TV está ligada em 110 V ou 220 V']::text[], '4K pede conexão estável de uns 15 Mbps ou mais. Sinal fraco no cômodo da TV é a causa mais comum.', 'Netflix / Wi-Fi', true, now()),
  ('inf-37', 'informatica', 'rede', 'Qual é a diferença prática entre as redes de 2,4 GHz e 5 GHz?', array['5 GHz rende mais perto; 2,4 GHz vai mais longe', '2,4 GHz é sempre mais rápida em qualquer lugar da casa', '5 GHz alcança mais longe e atravessa melhor as paredes', 'Não há diferença, só muda o nome que aparece na lista']::text[], 'Perto do roteador, 5 GHz rende mais. Longe ou atrás de paredes, 2,4 GHz costuma ficar mais estável.', 'Netflix / Wi-Fi', true, now()),
  ('inf-38', 'informatica', 'rede', 'Qual é o comprimento máximo de um trecho de cabo de rede (Cat5e ou Cat6) entre dois equipamentos?', array['100 metros', '30 metros', '500 metros, se o cabo for Cat6', 'Não tem limite, se o cabo for blindado']::text[], 'O limite do enlace de par trançado é de 100 m. Para ir mais longe, coloca-se um switch ou outro equipamento ativo no caminho.', 'Cabo de rede', true, now()),
  ('inf-39', 'informatica', 'rede', 'Montando um cabo de rede comum, como crimpar as pontas?', array['As duas no mesmo padrão (T568A ou T568B)', 'Cada ponta num padrão, sempre', 'Qualquer ordem de cores', 'Só os fios laranja e verde, o resto sobra']::text[], 'O mesmo padrão nas duas pontas faz o cabo direto, que é o usado em casa. Um padrão em cada ponta faz o cabo cruzado.', 'Cabo de rede', true, now()),
  ('inf-40', 'informatica', 'rede', 'O Wi-Fi não chega ao quarto dos fundos. Onde colocar o repetidor?', array['Onde ainda recebe bom sinal', 'Dentro do quarto que está sem sinal', 'Colado no roteador', 'No quintal']::text[], 'O repetidor só repete o sinal que recebe. Num lugar sem sinal, ele não tem o que repetir. Com cabo até um ponto de acesso, ou com Wi-Fi mesh, o resultado costuma ser melhor.', 'Prática de campo', true, now())
insert into public.quiz_tests (service_id, label, draw, pass, minutes) values ('limpeza', 'Limpeza', 10, 7, 10)
insert into private.quiz_questions (id, service_id, topic, question, options, why, source, active, updated_at) values
  ('lim-01', 'limpeza', 'produtos', 'Para "limpar melhor", pode misturar água sanitária com outro produto de limpeza?', array['Não, só se o rótulo autorizar', 'Sim, misturar sempre limpa mais e mais rápido', 'Sim, com qualquer desinfetante de cheiro', 'Sim, desde que seja num balde aberto e ventilado']::text[], 'A Anvisa orienta não misturar produtos de limpeza, salvo se o rótulo autorizar. Muitas misturas soltam gases tóxicos.', 'Anvisa', true, now()),
  ('lim-02', 'limpeza', 'produtos', 'O que acontece ao misturar água sanitária com vinagre ou produto ácido (como limpa-pedra)?', array['Libera gás cloro, tóxico e irritante', 'Vira um desinfetante mais forte e seguro', 'Nada, um anula o outro', 'Fica com cheiro melhor']::text[], 'Em contato com ácidos, o hipoclorito da água sanitária libera gás cloro.', 'Anvisa', true, now()),
  ('lim-03', 'limpeza', 'produtos', 'O cliente sugere água sanitária com álcool para desinfetar mais. O que você diz?', array['Que não se mistura: solta gás tóxico', 'Que é uma boa ideia para desinfetar mais', 'Que só pode em dia quente', 'Que só pode no banheiro']::text[], 'Água sanitária com álcool produz clorofórmio em gás. Com amônia, solta outros gases irritantes.', 'Anvisa', true, now()),
  ('lim-04', 'limpeza', 'produtos', 'Depois de usar dois produtos juntos, você sente ardência nos olhos, tosse e falta de ar. O que fazer?', array['Sair, ventilar e procurar atendimento', 'Continuar limpando', 'Jogar mais água sanitária para neutralizar a mistura', 'Beber leite e continuar o serviço']::text[], 'São os sintomas de intoxicação por gás de mistura. É preciso ar fresco e atendimento.', 'Anvisa', true, now()),
  ('lim-05', 'limpeza', 'produtos', 'Usar mais produto do que o rótulo manda limpa melhor?', array['Não, siga a diluição do rótulo', 'Sim, quanto mais concentrado melhor', 'Sim, se o chão estiver muito sujo', 'Sim, puro é sempre melhor']::text[], 'A Anvisa alerta que concentração maior não torna a limpeza mais eficiente e aumenta o risco.', 'Anvisa', true, now()),
  ('lim-06', 'limpeza', 'produtos', 'Um vendedor de porta em porta oferece água sanitária barata, sem rótulo. Pode usar no serviço?', array['Não, é clandestino', 'Pode, porque água sanitária é tudo igual', 'Pode, se o cheiro for forte, que mostra que é boa', 'Pode, se diluir mais do que o normal']::text[], 'Produto sem registro não passa por avaliação de segurança. A água sanitária clandestina é a que mais faz vítimas, por excesso de soda cáustica.', 'Anvisa', true, now()),
  ('lim-07', 'limpeza', 'produtos', 'Pode passar produto de limpeza para uma garrafa de refrigerante, para facilitar?', array['Não, fica na embalagem original', 'Pode, se escrever o nome do produto na garrafa', 'Pode, se for garrafa transparente e sem rótulo', 'Pode, se for só durante o dia de limpeza']::text[], 'Em garrafa de bebida, alguém pode tomar por engano, principalmente criança. A embalagem original tem rótulo e instruções.', 'Anvisa', true, now()),
  ('lim-08', 'limpeza', 'produtos', 'O que fazer com a embalagem vazia de um produto de limpeza?', array['Inutilizar e descartar, sem reaproveitar', 'Lavar bem e usar para guardar água de beber', 'Dar para as crianças brincarem depois de lavar', 'Guardar para encher com outro produto']::text[], 'A embalagem sempre fica com resíduo. A Anvisa pede inutilizar e descartar, de preferência na reciclagem.', 'Anvisa', true, now()),
  ('lim-09', 'limpeza', 'superficies', 'Como limpar uma bancada de mármore?', array['Detergente neutro', 'Vinagre com limão, que tira mancha e brilha', 'Água sanitária pura, que desinfeta a pedra', 'Sapólio e palha de aço nas manchas']::text[], 'O mármore é poroso e sensível a ácido. Vinagre, limão e água sanitária mancham e corroem.', 'Pedras naturais', true, now()),
  ('lim-10', 'limpeza', 'superficies', 'Caiu limão ou vinho na bancada de mármore. O que fazer?', array['Secar logo', 'Deixar secar sozinho', 'Esfregar com palha de aço', 'Jogar água sanitária por cima']::text[], 'O ácido mancha a pedra rápido. Quanto antes secar, menor a mancha.', 'Pedras naturais', true, now()),
  ('lim-11', 'limpeza', 'superficies', 'Como limpar geladeira, fogão ou cuba de aço inox?', array['Detergente neutro, sem cloro', 'Palha de aço', 'Água sanitária', 'Sapólio em pó com esponja dupla face']::text[], 'O fabricante pede detergente neutro e proíbe palha de aço e abrasivos, que riscam. O cloro mancha o inox.', 'Manual Tramontina', true, now()),
  ('lim-12', 'limpeza', 'superficies', 'A cuba de inox está com pontos marrons, parecendo ferrugem. O que é mais provável?', array['Cloro; limpar e secar após o uso', 'Defeito de fábrica da cuba', 'Falta de água sanitária na limpeza diária', 'Sujeira de café e chá grudada no metal']::text[], 'O manual da cuba associa as manchas marrons ao cloro e pede secar a peça depois de cada uso.', 'Manual Tramontina', true, now()),
  ('lim-13', 'limpeza', 'seguranca', 'Ao usar água sanitária ou desengordurante, o que proteger?', array['As mãos, com luvas', 'Só o cabelo, com touca', 'Nada, é produto de uso doméstico', 'Os pés, com chinelo de borracha']::text[], 'Esses produtos irritam e ressecam a pele. Luva é o mínimo.', 'Anvisa', true, now()),
  ('lim-14', 'limpeza', 'seguranca', 'Vai lavar o banheiro com produto forte. Como deixar o ambiente?', array['Ventilado', 'Fechado, para o cheiro do produto agir', 'Com o chuveiro quente ligado para o vapor ajudar', 'Com a porta trancada para ninguém entrar']::text[], 'Ventilar tira os vapores do produto. Banheiro fechado concentra os vapores e causa mal-estar.', 'Anvisa', true, now()),
  ('lim-15', 'limpeza', 'tecnica', 'Qual é a ordem certa para limpar um cômodo?', array['De cima para baixo, do limpo para o sujo', 'Começar pelo chão', 'Começar pelo vaso e depois passar para a pia', 'Tanto faz']::text[], 'Limpando de cima para baixo, a sujeira que cai vai para o que ainda vai ser limpo. Do limpo para o sujo, não se espalha sujeira.', 'Prática de campo', true, now()),
  ('lim-16', 'limpeza', 'tecnica', 'Pode usar o mesmo pano no banheiro e na cozinha?', array['Não, panos separados', 'Pode, se lavar com água entre um e outro', 'Pode, se for um pano novo de microfibra', 'Pode, se limpar a cozinha primeiro']::text[], 'O pano do banheiro leva germes para onde se prepara comida.', 'Prática de campo', true, now()),
  ('lim-17', 'limpeza', 'seguranca', 'Antes de limpar o micro-ondas ou a geladeira por dentro, o que fazer?', array['Tirar da tomada', 'Deixar ligado para ver a luz', 'Jogar água direto na tomada para limpar', 'Nada, é só passar pano']::text[], 'Água e eletricidade juntas dão choque. Tire o aparelho da tomada antes.', 'Prática de campo', true, now()),
  ('lim-18', 'limpeza', 'conduta', 'Limpando um quarto, você acha joias e dinheiro fora do lugar. O que fazer?', array['Não mexer e avisar o cliente', 'Guardar numa gaveta', 'Levar para casa e devolver no outro dia', 'Juntar tudo numa sacola e entregar no fim do mês']::text[], 'Avisar protege você e o cliente. Mexer sem avisar gera desconfiança.', 'Prática de campo', true, now()),
  ('lim-19', 'limpeza', 'seguranca', 'Casa com criança pequena e cachorro. Onde deixar os produtos e o balde durante a limpeza?', array['Fora do alcance deles', 'No chão, perto da porta, para pegar fácil', 'Em cima do sofá', 'No banheiro']::text[], 'Intoxicação de criança com produto de limpeza é comum. Produto e balde ficam sempre fora do alcance.', 'Anvisa', true, now()),
  ('lim-20', 'limpeza', 'seguranca', 'O piso ficou molhado e escorregadio. O que fazer?', array['Avisar e secar ou sinalizar', 'Nada, o piso seca sozinho em poucos minutos', 'Passar cera para o piso secar mais rápido', 'Apagar a luz para ninguém entrar']::text[], 'Piso molhado causa queda, principalmente de idosos e crianças.', 'Prática de campo', true, now())
insert into public.quiz_tests (service_id, label, draw, pass, minutes) values ('montagem-moveis', 'Montagem de móveis', 15, 11, 15)
insert into private.quiz_questions (id, service_id, topic, question, options, why, source, active, updated_at) values
  ('mon-01', 'montagem-moveis', 'preparo', 'Chegou no cliente com o móvel embalado. O que fazer antes de montar?', array['Conferir as peças com a lista do manual', 'Começar pela porta, que é a parte mais difícil de alinhar', 'Abrir todas as caixas e jogar fora a embalagem para ganhar espaço', 'Separar só os parafusos por tamanho e começar pela base']::text[], 'O manual pede examinar todas as peças antes. Faltando peça, é melhor saber antes de começar do que no meio da montagem.', 'Manual do móvel', true, now()),
  ('mon-02', 'montagem-moveis', 'preparo', 'Onde montar o móvel?', array['No chão plano, forrado com o papelão', 'Em cima da cama, que é macia e não risca as peças', 'Em qualquer canto livre', 'Direto no piso, que é mais firme para parafusar']::text[], 'O fabricante pede superfície plana e sugere forrar com a embalagem para não riscar o móvel nem o piso.', 'Manual Tramontina', true, now()),
  ('mon-03', 'montagem-moveis', 'montagem', 'Como apertar os parafusos durante a montagem?', array['Sem aperto total; aperto final no fim, no plano', 'Apertando bem cada parafuso assim que ele é colocado', 'Apertando só os parafusos de baixo', 'Deixando todos frouxos para o móvel se acomodar sozinho']::text[], 'Apertar tudo no começo deixa o móvel torto. O manual pede montar solto e fazer o aperto final com o móvel em superfície plana.', 'Manual Tramontina', true, now()),
  ('mon-04', 'montagem-moveis', 'montagem', 'Usando parafusadeira em MDF ou MDP, como regular?', array['Torque baixo na embreagem', 'Torque máximo', 'Velocidade máxima e sem embreagem, para entrar de uma vez', 'Tanto faz']::text[], 'Torque demais esmaga as fibras da chapa e a rosca vira pó. Depois disso o parafuso não segura mais.', 'Fabricantes de MDF', true, now()),
  ('mon-05', 'montagem-moveis', 'reparo', 'O furo do parafuso espanou no MDP. O que fazer?', array['Cavilha colada no furo e furar de novo', 'Colocar um parafuso bem mais grosso no mesmo furo', 'Encher o furo com papel ou palito e parafusar', 'Deixar sem esse parafuso, os outros seguram']::text[], 'Parafuso mais grosso abre ainda mais a chapa. A cavilha colada recompõe o material para a rosca.', 'Fabricantes de MDF', true, now()),
  ('mon-06', 'montagem-moveis', 'montagem', 'O manual pede cola nas cavilhas. Pode pular essa parte?', array['Não, a cola faz parte da estrutura', 'Pode, a cavilha só serve para alinhar as peças', 'Pode, desde que os parafusos fiquem bem apertados', 'Só vale usar se sobrar cola no fim da montagem']::text[], 'Seguir o manual é responsabilidade do montador e garante a estrutura. Sem cola, as juntas ficam frouxas com o uso.', 'Manual do móvel', true, now()),
  ('mon-07', 'montagem-moveis', 'parede', 'Antes de furar a parede para fixar um armário, o que verificar?', array['Onde passam canos e fios embutidos', 'Só se a parede é de tijolo ou de concreto, pela cor do pó', 'Nada, é só furar onde o cliente marcou com lápis', 'Se a parede foi pintada recentemente e a tinta já secou']::text[], 'Os fabricantes pedem localizar os canos embutidos para não furá-los. Os fios costumam subir e descer alinhados com tomadas e interruptores.', 'Manual Lorenzetti', true, now()),
  ('mon-08', 'montagem-moveis', 'seguranca', 'Casa com criança pequena, cômoda alta com gavetas. O que fazer?', array['Fixar na parede com o kit antitombamento', 'Nada, desde que a cômoda seja pesada e larga', 'Só avisar os pais para não deixar as gavetas abertas', 'Colocar a cômoda sobre um tapete grosso que segure']::text[], 'Criança subindo nas gavetas desloca o peso para a frente e o móvel tomba. A recomendação é fixar móveis altos na parede.', 'CPSC (EUA)', true, now()),
  ('mon-09', 'montagem-moveis', 'seguranca', 'Por que uma cômoda tomba quando várias gavetas ficam abertas?', array['O peso vai para a frente da base', 'As corrediças ficam mais leves e soltam do trilho', 'O fundo do móvel se solta com o peso das gavetas', 'A umidade do quarto deixa as laterais moles']::text[], 'Com as gavetas abertas, o centro de gravidade avança. Com uma criança pendurada, ele sai da base e o móvel cai.', 'CPSC (EUA)', true, now()),
  ('mon-10', 'montagem-moveis', 'seguranca', 'Onde orientar o cliente a guardar os itens mais pesados?', array['Embaixo', 'Nas prateleiras de cima, para sobrar espaço', 'Distribuídos no topo, para o peso firmar o móvel', 'Na porta, que tem dobradiças reforçadas']::text[], 'Peso embaixo deixa o móvel mais estável e reduz o risco de tombar.', 'CPSC (EUA)', true, now()),
  ('mon-11', 'montagem-moveis', 'seguranca', 'O manual diz que o móvel suporta no máximo 30 kg. O cliente quer pôr 50 kg de livros. O que você diz?', array['Que passa do limite e pode quebrar', 'Que pode, se reforçar com mais parafusos', 'Que pode', 'Que pode, desde que os livros fiquem em cima']::text[], 'O peso máximo vem no manual e garante a estrutura. Acima dele o móvel pode ceder.', 'Manual do móvel', true, now()),
  ('mon-12', 'montagem-moveis', 'parede', 'Qual broca usar para uma bucha de 8 mm?', array['Broca de 8 mm, no diâmetro da bucha', 'Broca de 10 mm', 'Broca de 4 mm, para ficar justo', 'Qualquer uma']::text[], 'As fichas da Fischer pedem broca do mesmo diâmetro da bucha. Furo maior deixa a bucha rodando em falso.', 'Fischer', true, now()),
  ('mon-13', 'montagem-moveis', 'parede', 'A bucha não firma no tijolo furado. O que é mais provável?', array['Furo largo ou raso, ou bucha errada', 'A parede é forte demais para a bucha abrir', 'O parafuso é novo e ainda não amaciou a bucha', 'A bucha precisa ser molhada antes de entrar']::text[], 'No oco, a bucha universal se entrelaça em vez de só expandir. Precisa do diâmetro certo e da profundidade mínima, e a percussão costuma quebrar as paredes internas do tijolo.', 'Fischer', true, now()),
  ('mon-14', 'montagem-moveis', 'parede', 'Para furar parede de concreto, o que usar?', array['Broca de vídea, com impacto', 'Broca de madeira, sem impacto, para não rachar', 'Broca de metal comum, com bastante pressão', 'Broca de vídea, sem impacto']::text[], 'Concreto exige broca de vídea e impacto. Broca de madeira ou metal não fura e se perde.', 'Fischer', true, now()),
  ('mon-15', 'montagem-moveis', 'parede', 'Vai fixar uma prateleira em parede de drywall (gesso acartonado). Qual bucha usar?', array['Bucha própria para drywall ou o montante', 'Bucha comum de nylon', 'Só o parafuso direto no gesso', 'Prego com cola de contato no lugar da bucha']::text[], 'Bucha comum não segura no gesso. Para chapa oca, existem buchas próprias, e o mais firme é fixar no montante.', 'Knauf / Placo', true, now()),
  ('mon-16', 'montagem-moveis', 'parede', 'O cliente quer um armário aéreo pesado numa parede de drywall. O que fazer?', array['Nos montantes ou num reforço de madeira', 'Com mais buchas comuns espalhadas pela chapa', 'Colando o armário na parede com silicone', 'Só no gesso, com parafusos bem longos']::text[], 'A chapa sozinha aguenta pouco por ponto. Carga pesada vai na estrutura ou em reforço previsto.', 'Knauf / Placo', true, now()),
  ('mon-17', 'montagem-moveis', 'parede', 'O kit de fixação do móvel na parede veio sem bucha. Por quê?', array['A bucha depende do tipo de parede', 'Porque esse tipo de móvel não precisa de bucha', 'Porque o fabricante esqueceu de colocar na caixa', 'Porque a fixação é feita com prego, não com bucha']::text[], 'Os fabricantes deixam a bucha de fora porque ela muda para tijolo, concreto ou drywall. O montador escolhe a certa.', 'CPSC (EUA)', true, now()),
  ('mon-18', 'montagem-moveis', 'montagem', 'Para que serve o fundo (as costas) do guarda-roupa?', array['Ele trava o móvel no esquadro', 'Só para não aparecer a parede atrás das roupas', 'Nada, o móvel fica firme sem ele', 'Só para pendurar cabides na parte de trás']::text[], 'O fundo pregado ou encaixado impede o móvel de entortar de lado. Sem ele, o móvel fica bambo.', 'Prática de campo', true, now()),
  ('mon-19', 'montagem-moveis', 'montagem', 'Como conferir se o móvel está no esquadro antes de pregar o fundo?', array['Medindo as duas diagonais', 'Olhando de longe se as laterais estão retas', 'Medindo só a altura das duas laterais', 'Apertando todos os parafusos e vendo se trava']::text[], 'Diagonais iguais indicam ângulos retos. Se o fundo for pregado torto, as portas nunca alinham.', 'Prática de campo', true, now()),
  ('mon-20', 'montagem-moveis', 'ajuste', 'Depois de pronto, o móvel ficou com uma porta abrindo sozinha. O que verificar primeiro?', array['O nivelamento do móvel', 'A marca da dobradiça', 'A espessura da porta', 'O peso das roupas penduradas no cabideiro']::text[], 'Móvel desnivelado faz porta abrir sozinha e desalinhar. Nivelar resolve antes de mexer na regulagem.', 'Prática de campo', true, now()),
  ('mon-21', 'montagem-moveis', 'ajuste', 'As portas do armário ficaram desalinhadas. Como ajustar?', array['Pela regulagem da dobradiça', 'Desmontando o móvel inteiro e montando de novo', 'Lixando a borda da porta até alinhar', 'Trocando por dobradiças maiores e mais fortes']::text[], 'A dobradiça com regulagem tem três ajustes. Primeiro observe as frestas de frente, depois gire o parafuso certo.', 'Prática de campo', true, now()),
  ('mon-22', 'montagem-moveis', 'montagem', 'Ao instalar as corrediças de uma gaveta, qual é o cuidado?', array['Na mesma altura e paralelas', 'Uma um pouco mais alta', 'Tanto faz a altura, a gaveta se ajeita com o uso', 'Só uma corrediça já basta numa gaveta pequena']::text[], 'Corrediças desalinhadas travam a gaveta e forçam os parafusos até soltar.', 'Prática de campo', true, now()),
  ('mon-23', 'montagem-moveis', 'parede', 'Precisa furar o azulejo da cozinha para fixar um armário. Como fazer?', array['Fita crepe e furar o azulejo sem impacto', 'Furar direto no impacto', 'Bater um prego antes para marcar o ponto', 'Furar no meio da junta']::text[], 'O impacto racha o azulejo. A fita evita que a broca escorregue e lascar o esmalte.', 'Prática de campo', true, now()),
  ('mon-24', 'montagem-moveis', 'seguranca', 'Uma peça veio quebrada. O que fazer?', array['Não usar e pedir peça original', 'Colar a parte quebrada e montar assim mesmo', 'Usar uma peça parecida de outro móvel', 'Montar sem ela']::text[], 'O manual diz para não usar o produto com peça quebrada e usar só reposição aprovada pelo fabricante.', 'Manual do móvel', true, now()),
  ('mon-25', 'montagem-moveis', 'montagem', 'Sobre o manual de montagem, qual frase está certa?', array['Seguir o manual é responsabilidade de quem monta', 'Montador experiente não precisa olhar o manual', 'O manual é feito só para o cliente que monta sozinho', 'Pode trocar a ordem dos passos se ficar mais rápido']::text[], 'O próprio manual diz isso: seguir as instruções é responsabilidade do montador e é o que garante a estrutura.', 'Manual do móvel', true, now()),
  ('mon-26', 'montagem-moveis', 'entrega', 'Como orientar o cliente a limpar o móvel novo?', array['Pano úmido e depois seco', 'Álcool e palha de aço nas manchas mais difíceis', 'Água sanitária diluída para desinfetar as gavetas', 'Lustra-móveis com solvente toda semana']::text[], 'É a orientação de limpeza do fabricante. Produtos químicos e abrasivos estragam o acabamento.', 'Manual do móvel', true, now()),
  ('mon-27', 'montagem-moveis', 'seguranca', 'O cliente quer o móvel colado no fogão ou no aquecedor. O que avisar?', array['Que calor e chama perto são um risco', 'Que não tem problema', 'Que só precisa passar verniz para proteger', 'Que é até melhor']::text[], 'As advertências do fabricante citam o risco de chama aberta e outras fontes de calor perto do produto.', 'Manual do móvel', true, now()),
  ('mon-28', 'montagem-moveis', 'seguranca', 'Ao terminar, o que conferir nas ferragens (parafusos, porcas, ponteiras)?', array['Se estão firmes e bem rosqueadas', 'Só se estão brilhando e sem marca de ferramenta', 'Nada, quem confere as ferragens é o cliente', 'Se sobrou alguma ferragem para guardar']::text[], 'O manual pede todas as ferragens bem fixadas e atarraxadas para não causar ferimentos.', 'Manual do móvel', true, now()),
  ('mon-29', 'montagem-moveis', 'montagem', 'Guarda-roupa alto montado deitado no chão. Qual é o cuidado ao levantar?', array['Ver se a diagonal passa sob o teto e ter ajuda', 'Levantar sozinho, puxando pelo topo devagar', 'Levantar segurando pela porta, que é a parte mais firme', 'Nenhum cuidado, é só levantar com firmeza']::text[], 'A diagonal do móvel é maior que a altura. Se o teto for baixo, o móvel bate antes de ficar em pé e força as juntas.', 'Prática de campo', true, now()),
  ('mon-30', 'montagem-moveis', 'seguranca', 'O que usar para proteger os olhos ao furar parede?', array['Óculos de proteção', 'Nada, é só fechar os olhos na hora', 'Óculos de sol', 'Boné']::text[], 'Furar parede solta pó e lascas. Óculos de proteção é o mínimo.', 'Prática de campo', true, now())
insert into public.quiz_tests (service_id, label, draw, pass, minutes) values ('pintor', 'Pintura', 15, 11, 15)
insert into private.quiz_questions (id, service_id, topic, question, options, why, source, active, updated_at) values
  ('pin-01', 'pintor', 'preparo', 'A parede foi rebocada semana passada. O cliente quer pintar amanhã. O que você orienta?', array['Esperar uns 30 dias e usar selador', 'Pintar amanhã mesmo, porque a tinta ajuda a parede a secar', 'Passar massa corrida para fechar os poros e pintar em seguida', 'Molhar bem a parede antes, para a tinta pegar no reboco']::text[], 'Reboco novo ainda solta umidade e alcalinidade. O fabricante pede no mínimo 30 dias e selador. Se não puder esperar, fundo preparador.', 'Boletim Coral', true, now()),
  ('pin-02', 'pintor', 'preparo', 'Passando a mão, a parede solta pó e grãos. O que aplicar antes da tinta?', array['Fundo preparador de paredes', 'Selador acrílico', 'Só a tinta, com uma demão a mais para firmar', 'Massa corrida direto, para segurar o pó']::text[], 'O selador é para superfície nova e firme. Parede que esfarela tem baixa coesão e pede fundo preparador.', 'Suvinil', true, now()),
  ('pin-03', 'pintor', 'preparo', 'Parede antiga pintada com cal. Como preparar para tinta acrílica?', array['Tirar o solto, lixar e usar fundo preparador', 'Pintar por cima direto', 'Molhar a parede e pintar enquanto ainda está úmida', 'Passar massa acrílica grossa por cima da cal']::text[], 'A cal esfarela e a tinta descasca junto com ela. O boletim pede remover o que estiver solto e usar fundo preparador.', 'Boletim Coral', true, now()),
  ('pin-04', 'pintor', 'preparo', 'A parede tem manchas de mofo. O que fazer antes de pintar?', array['Água sanitária 1:1, 6 horas, enxaguar e secar', 'Pintar por cima com tinta antimofo', 'Passar massa corrida por cima das manchas e pintar', 'Lixar a seco as manchas e pintar com duas demãos']::text[], 'Pintar por cima não mata o mofo e ele volta. O boletim pede água sanitária 1:1, 6 horas de espera, enxágue e secagem.', 'Boletim Coral', true, now()),
  ('pin-05', 'pintor', 'preparo', 'A parede está úmida por causa de uma infiltração. O cliente quer só pintar. O que você faz?', array['Explico que antes é preciso resolver a umidade', 'Pinto com tinta mais grossa, que segura a umidade', 'Pinto com esmalte para impermeabilizar a parede', 'Passo massa corrida e pinto por cima']::text[], 'A orientação do fabricante é resolver o que causa a umidade antes de pintar. Senão a pintura bolha e descasca.', 'Boletim Coral', true, now()),
  ('pin-06', 'pintor', 'preparo', 'Vai pintar sobre uma tinta com brilho (esmalte ou acetinada). O que fazer antes?', array['Lixar até tirar o brilho', 'Nada, a tinta nova cobre e se prende sozinha', 'Molhar a parede para a tinta escorregar menos', 'Passar água sanitária para tirar a gordura do brilho']::text[], 'Sem lixar, a tinta nova não ancora no brilho e descasca.', 'Boletim Coral', true, now()),
  ('pin-07', 'pintor', 'preparo', 'Parede de cozinha com gordura. Como limpar antes de pintar?', array['Detergente neutro, enxaguar e secar', 'Álcool, e pintar enquanto ainda está molhado', 'Thinner direto na parede', 'Não precisa limpar']::text[], 'Gordura impede a aderência. O boletim pede lavar com detergente neutro, enxaguar e secar.', 'Boletim Coral', true, now()),
  ('pin-08', 'pintor', 'preparo', 'Para corrigir pequenas imperfeições, qual massa usar?', array['Corrida dentro, acrílica fora', 'Massa corrida em qualquer lugar, inclusive na fachada', 'Massa acrílica só no teto e corrida nas paredes', 'Gesso na fachada e massa corrida dentro']::text[], 'A massa corrida não aguenta tempo e umidade. Para área externa, usa-se massa acrílica.', 'Boletim Coral', true, now()),
  ('pin-09', 'pintor', 'preparo', 'Depois de lixar a parede, como tirar o pó?', array['Com pano úmido', 'Soprando', 'Com vassoura seca', 'Não precisa, a tinta segura o pó']::text[], 'O boletim sempre manda eliminar o pó com pano úmido antes de pintar. Pó deixa a tinta sem aderência.', 'Boletim Coral', true, now()),
  ('pin-10', 'pintor', 'preparo', 'O fabricante pede um fundo específico para gesso corrido. Por quê?', array['Gesso corrido absorve muito e pede fundo próprio', 'Porque o gesso não aceita nenhuma tinta comum', 'Porque é só propaganda, qualquer fundo serve', 'Porque o gesso corrido é próprio para área externa']::text[], 'O boletim indica fundo preparador para gesso em geral, mas para gesso corrido pede produto próprio. Gesso também não deve ficar exposto ao tempo.', 'Boletim Coral', true, now()),
  ('pin-11', 'pintor', 'aplicacao', 'Em qual condição o fabricante pede para não pintar?', array['Chuva, menos de 10 °C, mais de 40 °C ou ar muito úmido', 'Dia nublado, mesmo sem chuva e com temperatura amena', 'Temperatura de 25 °C com sol fraco', 'Depois das 14 h, quando o sol muda de lado']::text[], 'Essas condições mudam a secagem e prejudicam o acabamento. O boletim pede evitar.', 'Boletim Coral', true, now()),
  ('pin-12', 'pintor', 'aplicacao', 'Quanto esperar entre uma demão e outra?', array['O tempo da lata (aqui, 4 horas)', 'Pode passar a segunda demão logo em seguida', 'Um dia inteiro', 'Só até a primeira demão parar de escorrer']::text[], 'Demão sobre demão ainda molhada enruga e escorre. Cada tinta traz o tempo entre demãos no boletim.', 'Boletim Coral', true, now()),
  ('pin-13', 'pintor', 'aplicacao', 'Como diluir a tinta?', array['Com água, no máximo indicado na lata', 'Meio a meio com água, para render mais', 'Com thinner, mesmo sendo tinta acrílica', 'À vontade, até a tinta ficar bem rala']::text[], 'Diluir demais tira a cobertura e a resistência da tinta. A proporção máxima vem no boletim.', 'Boletim Coral', true, now()),
  ('pin-14', 'pintor', 'aplicacao', 'O que fazer antes de diluir a tinta da lata?', array['Misturar bem com espátula', 'Nada, é só colocar a água e começar', 'Deixar a lata aberta uma hora para respirar', 'Sacudir a lata fechada por alguns segundos']::text[], 'O boletim pede misturar antes de diluir, porque os pigmentos assentam no fundo.', 'Boletim Coral', true, now()),
  ('pin-15', 'pintor', 'aplicacao', 'Cor forte (vermelho, amarelo) sobre parede branca. Quantas demãos esperar?', array['Pode precisar de mais de 2 ou 3 demãos', 'Uma demão sempre basta com tinta boa', 'Exatamente 2 demãos, nunca mais que isso', 'Depende só do rolo, não da cor']::text[], 'O boletim indica 2 a 3 demãos, mas avisa que algumas cores e superfícies pedem mais.', 'Boletim Coral', true, now()),
  ('pin-16', 'pintor', 'seguranca', 'Pintando um quarto, como deve ficar o ambiente?', array['Ventilado, com janelas abertas', 'Fechado, para secar mais rápido', 'Com ventilador soprando direto na parede molhada', 'Fechado e com o ar-condicionado no máximo']::text[], 'Ventilação tira o cheiro e os vapores. O fabricante associa o pouco cheiro ao ambiente ventilado.', 'Boletim Coral', true, now()),
  ('pin-17', 'pintor', 'metal', 'Vai pintar um portão de ferro com ferrugem. Qual é a ordem certa?', array['Tirar a ferrugem, fundo para ferro e esmalte', 'Passar esmalte direto por cima da ferrugem', 'Passar massa corrida nos pontos de ferrugem e pintar', 'Lavar com água sanitária e pintar com tinta látex']::text[], 'O fundo para ferro protege contra corrosão e dá base ao esmalte. Por cima da ferrugem solta, nada segura.', 'Suvinil / Coral', true, now()),
  ('pin-18', 'pintor', 'metal', 'Calha ou portão galvanizado novo. Qual fundo usar?', array['Fundo próprio para galvanizado', 'Zarcão, igual ao do ferro', 'Nenhum, o esmalte segura direto', 'Selador acrílico de parede']::text[], 'Galvanizado e alumínio pedem fundo específico. Sem ele, a tinta descasca em pouco tempo.', 'Suvinil / Coral', true, now()),
  ('pin-19', 'pintor', 'metal', 'Madeira resinosa, como pinus, vai receber verniz ou esmalte. O que aplicar antes?', array['Fundo isolante para madeira', 'Nada, é só lixar bem a madeira', 'Água sanitária para tirar a resina', 'Massa corrida de parede para fechar os poros']::text[], 'A resina da madeira mancha e atrapalha a secagem. O fabricante pede fundo isolante.', 'Suvinil / Coral', true, now()),
  ('pin-20', 'pintor', 'seguranca', 'Pintar a fachada de cima de um andaime a 3 metros. O que a norma diz?', array['É trabalho em altura, pela NR-35', 'Só é trabalho em altura acima de 10 metros', 'Não tem regra específica para pintor', 'Basta ter cuidado e não olhar para baixo']::text[], 'A NR-35 define trabalho em altura como atividade acima de 2 m do nível inferior com risco de queda.', 'NR-35', true, now()),
  ('pin-21', 'pintor', 'seguranca', 'Antes de usar a escada, o que conferir?', array['Piso firme, escada travada e degraus bons', 'Só se a escada é alta o bastante para o teto', 'Nada, é só subir rápido e com cuidado', 'Se tem lugar para apoiar a lata no último degrau']::text[], 'Queda de escada é um dos acidentes mais comuns na pintura. Mesmo abaixo de 2 m são exigidas medidas preventivas.', 'NR-35', true, now()),
  ('pin-22', 'pintor', 'limpeza', 'Como lavar o rolo e o pincel usados com tinta à base de água?', array['Água e sabão, sem jogar no bueiro', 'Com água no bueiro da rua', 'Com thinner, que limpa melhor qualquer tinta', 'Jogar o rolo fora sempre que terminar']::text[], 'A orientação é lavar com água e sabão e não descartar a água em bueiro, boca de lobo ou solo.', 'ABRAFATI', true, now()),
  ('pin-23', 'pintor', 'limpeza', 'Como limpar o pincel usado com esmalte à base de solvente?', array['Com o solvente da diluição; resíduo na areia', 'Com água e sabão, esfregando bem as cerdas', 'No tanque, com bastante água corrente', 'Deixando de molho em água até o dia seguinte']::text[], 'Solvente não sai com água. O resíduo vai em areia e, depois que evapora, a areia vai para o lixo.', 'ABRAFATI', true, now()),
  ('pin-24', 'pintor', 'limpeza', 'Sobrou tinta no fim do serviço. O que fazer?', array['Guardar, doar ou levar a um ponto de coleta', 'Jogar na pia com bastante água corrente', 'Jogar no terreno baldio, longe das casas', 'Misturar com a água de lavar o quintal']::text[], 'A ABRAFATI recomenda reaproveitar ou doar e usar pontos do RetornaTinta. Tinta no ralo contamina a água.', 'ABRAFATI', true, now()),
  ('pin-25', 'pintor', 'preparo', 'Antes de pintar em volta das tomadas, o que fazer?', array['Desligar o disjuntor e tirar os espelhos', 'Pintar por cima dos espelhos com cuidado', 'Tirar os espelhos com tudo ligado, sem encostar nos fios', 'Cobrir os espelhos com sabão para a tinta não pegar']::text[], 'Tirar o espelho expõe os contatos. Com o disjuntor desligado, não há risco de choque com o pincel ou a espátula.', 'Prática de campo', true, now()),
  ('pin-26', 'pintor', 'preparo', 'O que proteger antes de começar a pintar o cômodo?', array['Piso, móveis, rodapés e batentes', 'Nada, depois se limpa tudo com pano', 'Só o teto, que é onde mais respinga', 'Só a janela e o vidro']::text[], 'Respingo de tinta seca é difícil de tirar sem estragar o piso ou o móvel.', 'Prática de campo', true, now()),
  ('pin-27', 'pintor', 'aplicacao', 'Teto e paredes no mesmo cômodo. Por onde começar?', array['Pelo teto', 'Pelas paredes, depois o teto', 'Pelo rodapé, de baixo para cima', 'Tanto faz, se proteger o piso']::text[], 'Pintando o teto primeiro, os respingos caem na parede que ainda vai ser pintada.', 'Prática de campo', true, now()),
  ('pin-28', 'pintor', 'diagnostico', 'A pintura nova fez bolhas em poucos dias. Qual é a causa mais provável?', array['Umidade na parede', 'Rolo novo demais', 'Cor clara', 'Tinta de marca boa, que é mais grossa']::text[], 'A umidade presa empurra a película de tinta. Por isso os fabricantes pedem superfície seca e resolver a umidade antes.', 'Boletim Coral', true, now()),
  ('pin-29', 'pintor', 'diagnostico', 'A pintura descascou em placas um ano depois. O cliente conta que tinham pintado sobre cal. O que explica?', array['Faltou preparar a cal com fundo preparador', 'A tinta era branca e não aguentou o sol', 'Choveu no dia seguinte à pintura', 'Usaram rolo de lã em vez de pincel']::text[], 'A cal não segura a tinta acrílica e solta junto com ela. O preparo certo é remover e usar fundo preparador.', 'Boletim Coral', true, now()),
  ('pin-30', 'pintor', 'preparo', 'Parede nova e firme, já curada. Qual é a função do selador?', array['Uniformizar a absorção', 'Corrigir buracos fundos e trincas na parede', 'Matar o mofo antes de pintar', 'Substituir a tinta de acabamento em parede nova']::text[], 'O selador é para superfícies novas e firmes. Ele sela a porosidade para a tinta render e ficar uniforme.', 'Suvinil', true, now())
